(function(){
 if(typeof window==='undefined')return;
 var DATA=[
  {"key":"M1:Welcome to the Course","rows":[{"q":"Welcome to the Course: What helps a learner connect the course with a practical funding task?","opts":["Practise with a sample case","Verify work against requirements","Keep evidence of learning","Plan purposeful study"],"correct":3,"exp":"A study plan identifies the intended skills, sequence and realistic time for practice.","module":1,"topic":"M1:Welcome to the Course"},{"q":"Welcome to the Course: How can a learner build drafting skill without submitting a real application prematurely?","opts":["Plan purposeful study","Verify work against requirements","Practise with a sample case","Keep evidence of learning"],"correct":2,"exp":"A clearly labeled sample case permits practice without claiming it is an authorized organizational submission.","module":1,"topic":"M1:Welcome to the Course"},{"q":"Welcome to the Course: What should follow completing a practice proposal?","opts":["Plan purposeful study","Verify work against requirements","Practise with a sample case","Keep evidence of learning"],"correct":1,"exp":"Compare the work with the relevant brief or guidelines and check factual and budget consistency.","module":1,"topic":"M1:Welcome to the Course"},{"q":"Welcome to the Course: What documents development across proposals, budgets and fundraising exercises?","opts":["Keep evidence of learning","Plan purposeful study","Practise with a sample case","Verify work against requirements"],"correct":0,"exp":"A portfolio records authorized examples, feedback and reflection rather than only course attendance.","module":1,"topic":"M1:Welcome to the Course"}]},
  {"key":"M1:What is Grant Writing?","rows":[{"q":"What is Grant Writing?: What should be established before drafting for a particular funder?","opts":["Funder fit","Evidence-based case","Feasible proposal","Requirements compliance"],"correct":0,"exp":"Funder fit connects the applicant, purpose and proposed work with the opportunity's stated priorities and eligibility.","module":1,"topic":"M1:What is Grant Writing?"},{"q":"What is Grant Writing?: What supports a proposal's account of a community problem?","opts":["Funder fit","Feasible proposal","Evidence-based case","Requirements compliance"],"correct":2,"exp":"An evidence-based case uses relevant sources and consultation instead of invented statistics.","module":1,"topic":"M1:What is Grant Writing?"},{"q":"What is Grant Writing?: What shows that proposed activities can realistically be delivered?","opts":["Funder fit","Evidence-based case","Requirements compliance","Feasible proposal"],"correct":3,"exp":"A feasible proposal connects activities, capacity, timing, resources and intended results.","module":1,"topic":"M1:What is Grant Writing?"},{"q":"What is Grant Writing?: What must a polished application still satisfy?","opts":["Funder fit","Requirements compliance","Evidence-based case","Feasible proposal"],"correct":1,"exp":"Compliance includes the actual instructions, required documents and submission conditions; good writing alone does not establish it.","module":1,"topic":"M1:What is Grant Writing?"}]},
  {"key":"M1:What is Fundraising?","rows":[{"q":"What is Fundraising?: What explains why a cause merits support?","opts":["Case for support","Resource mobilization","Donor relationship","Accountable stewardship"],"correct":0,"exp":"A case for support connects a real need, credible response and the value a contribution can enable.","module":1,"topic":"M1:What is Fundraising?"},{"q":"What is Fundraising?: What describes seeking suitable support from several funding sources?","opts":["Case for support","Donor relationship","Accountable stewardship","Resource mobilization"],"correct":3,"exp":"Resource mobilization may combine individual giving, grants and other appropriate fundraising routes.","module":1,"topic":"M1:What is Fundraising?"},{"q":"What is Fundraising?: What develops trust beyond a single request for money?","opts":["Case for support","Resource mobilization","Donor relationship","Accountable stewardship"],"correct":2,"exp":"A donor relationship includes listening, relevant communication and respect for donor preferences.","module":1,"topic":"M1:What is Fundraising?"},{"q":"What is Fundraising?: What is required after funds are received?","opts":["Case for support","Resource mobilization","Accountable stewardship","Donor relationship"],"correct":2,"exp":"Stewardship respects agreed use, records resources responsibly and reports verified results.","module":1,"topic":"M1:What is Fundraising?"}]},
  {"key":"M1:Career Opportunities","rows":[{"q":"Career Opportunities: Which role primarily investigates and screens funding opportunities?","opts":["Grant researcher","Proposal writer","Fundraising officer","Grant manager"],"correct":0,"exp":"A grant researcher examines current funder information and records fit and requirements.","module":1,"topic":"M1:Career Opportunities"},{"q":"Career Opportunities: Which role primarily organizes evidence into an application narrative?","opts":["Grant researcher","Fundraising officer","Proposal writer","Grant manager"],"correct":2,"exp":"A proposal writer drafts a coherent response while working with authorized program and finance inputs.","module":1,"topic":"M1:Career Opportunities"},{"q":"Career Opportunities: Which role primarily develops campaigns and donor relationships?","opts":["Grant researcher","Proposal writer","Grant manager","Fundraising officer"],"correct":3,"exp":"A fundraising officer coordinates appropriate appeals, engagement and stewardship.","module":1,"topic":"M1:Career Opportunities"},{"q":"Career Opportunities: Which role primarily oversees obligations after an award?","opts":["Grant researcher","Grant manager","Proposal writer","Fundraising officer"],"correct":1,"exp":"A grant manager coordinates implementation, financial tracking, compliance and reporting.","module":1,"topic":"M1:Career Opportunities"}]},
  {"key":"M1:Types of Funding Organizations","rows":[{"q":"Types of Funding Organizations: Which type commonly issues public funding opportunities under defined program rules?","opts":["Charitable foundation","Government body","Corporate giving program","Individual donor"],"correct":1,"exp":"Government bodies fund according to their specific public programs and applicant requirements.","module":1,"topic":"M1:Types of Funding Organizations"},{"q":"Types of Funding Organizations: Which type commonly awards philanthropic funding under its own charitable priorities?","opts":["Government body","Charitable foundation","Corporate giving program","Individual donor"],"correct":1,"exp":"A charitable foundation has defined purposes and application arrangements that must be checked individually.","module":1,"topic":"M1:Types of Funding Organizations"},{"q":"Types of Funding Organizations: Which type is connected with a company's giving or community investment?","opts":["Government body","Charitable foundation","Corporate giving program","Individual donor"],"correct":2,"exp":"Corporate giving programs operate within the company's actual criteria and should not be confused automatically with sponsorship contracts.","module":1,"topic":"M1:Types of Funding Organizations"},{"q":"Types of Funding Organizations: Which type can provide a personal charitable contribution?","opts":["Government body","Individual donor","Charitable foundation","Corporate giving program"],"correct":1,"exp":"An individual donor's gift requires suitable communication, consent and respect for any accepted restrictions.","module":1,"topic":"M1:Types of Funding Organizations"}]},
  {"key":"M1:Ethics in Grant Writing","rows":[{"q":"Ethics in Grant Writing: What should a writer do when a requested statistic cannot be verified?","opts":["Authorized information use","Disclosed conflict","Honest uncertainty","Truthful evidence"],"correct":3,"exp":"Use verified evidence or state the gap rather than fabricate a number.","module":1,"topic":"M1:Ethics in Grant Writing"},{"q":"Ethics in Grant Writing: What should precede including a beneficiary story in an application?","opts":["Truthful evidence","Disclosed conflict","Authorized information use","Honest uncertainty"],"correct":2,"exp":"Check appropriate permission, privacy and safeguarding before using identifiable information.","module":1,"topic":"M1:Ethics in Grant Writing"},{"q":"Ethics in Grant Writing: What should a writer reveal if a personal interest may affect a funding recommendation?","opts":["Truthful evidence","Authorized information use","Disclosed conflict","Honest uncertainty"],"correct":2,"exp":"Disclosure enables the organization to apply suitable conflict safeguards.","module":1,"topic":"M1:Ethics in Grant Writing"},{"q":"Ethics in Grant Writing: How should a proposal describe an outcome that cannot be guaranteed?","opts":["Truthful evidence","Authorized information use","Disclosed conflict","Honest uncertainty"],"correct":3,"exp":"State the intended result, assumptions and relevant risks without promising certainty or guaranteed funding.","module":1,"topic":"M1:Ethics in Grant Writing"}]},
  {"key":"M1:Course Roadmap","rows":[{"q":"Course Roadmap: Why study grant terminology and eligibility before drafting a full proposal?","opts":["Foundational concepts","Integrated application","Portfolio development","Official completion review"],"correct":0,"exp":"Foundations help interpret opportunities and avoid building an application on incorrect assumptions.","module":1,"topic":"M1:Course Roadmap"},{"q":"Course Roadmap: What does the capstone combine from different teaching modules?","opts":["Foundational concepts","Portfolio development","Official completion review","Integrated application"],"correct":3,"exp":"An integrated application connects need, design, budget, fundraising and reporting logic.","module":1,"topic":"M1:Course Roadmap"},{"q":"Course Roadmap: What should a learner build progressively while completing practice projects?","opts":["Foundational concepts","Integrated application","Portfolio development","Official completion review"],"correct":2,"exp":"Portfolio development assembles evidence of skills and revisions across the program.","module":1,"topic":"M1:Course Roadmap"},{"q":"Course Roadmap: Where should a learner verify the current requirements for an official TIH certificate?","opts":["Foundational concepts","Integrated application","Official completion review","Portfolio development"],"correct":2,"exp":"Official completion and certificates remain managed in the TIH Learning Hub, separate from local app practice records.","module":1,"topic":"M1:Course Roadmap"}]},
  {"key":"M2:Understanding Grants","rows":[{"q":"Understanding Grants: What distinguishes a grant from unrestricted money available for any activity?","opts":["Conditional award","Defined purpose","Award agreement","Accountability"],"correct":1,"exp":"A grant commonly supports a defined purpose and must be interpreted using its actual conditions.","module":2,"topic":"M2:Understanding Grants"},{"q":"Understanding Grants: Why should an applicant not assume a grant is entirely obligation-free?","opts":["Defined purpose","Award agreement","Accountability","Conditional award"],"correct":3,"exp":"An award can require specified use, reporting and other conditions even where it is not a loan.","module":2,"topic":"M2:Understanding Grants"},{"q":"Understanding Grants: What document should be reviewed to understand accepted award obligations?","opts":["Defined purpose","Conditional award","Accountability","Award agreement"],"correct":3,"exp":"The award agreement and incorporated requirements establish the actual terms to be followed.","module":2,"topic":"M2:Understanding Grants"},{"q":"Understanding Grants: What supports a funder's confidence after an award?","opts":["Defined purpose","Conditional award","Award agreement","Accountability"],"correct":3,"exp":"Accountability records authorized use and verified delivery and communicates problems appropriately.","module":2,"topic":"M2:Understanding Grants"}]},
  {"key":"M2:Types of Grants","rows":[{"q":"Types of Grants: Which grant type supports a bounded set of activities and intended results?","opts":["Operating support","Project grant","Capital grant","Capacity-building grant"],"correct":1,"exp":"A project grant funds a defined intervention under the donor's specific conditions.","module":2,"topic":"M2:Types of Grants"},{"q":"Types of Grants: Which type may support an organization's ongoing work within agreed restrictions?","opts":["Project grant","Operating support","Capital grant","Capacity-building grant"],"correct":1,"exp":"Operating support concerns continuing organizational activity and still requires checking the actual award terms.","module":2,"topic":"M2:Types of Grants"},{"q":"Types of Grants: Which type may support facilities or durable assets?","opts":["Capital grant","Project grant","Operating support","Capacity-building grant"],"correct":0,"exp":"A capital grant concerns longer-lived assets, subject to its eligibility and use conditions.","module":2,"topic":"M2:Types of Grants"},{"q":"Types of Grants: Which type may support stronger systems or staff capability?","opts":["Project grant","Operating support","Capacity-building grant","Capital grant"],"correct":2,"exp":"Capacity-building grants develop the organization's ability to deliver its mission rather than assuming any expense is eligible.","module":2,"topic":"M2:Types of Grants"}]},
  {"key":"M2:Government Grants","rows":[{"q":"Government Grants: What should provide the authoritative requirements for a government funding opportunity?","opts":["Official notice","Applicant eligibility","Authorized registration","Public award obligations"],"correct":0,"exp":"Use the current official notice and application instructions rather than a third-party summary alone.","module":2,"topic":"M2:Government Grants"},{"q":"Government Grants: What must be checked before investing in a full application?","opts":["Official notice","Authorized registration","Public award obligations","Applicant eligibility"],"correct":3,"exp":"Applicant eligibility depends on the specific program and may include organizational, geographic and activity conditions.","module":2,"topic":"M2:Government Grants"},{"q":"Government Grants: What should be arranged before a portal deadline where the program requires registration?","opts":["Official notice","Authorized registration","Applicant eligibility","Public award obligations"],"correct":1,"exp":"Complete the applicable authorized registration process early; requirements vary by funder and jurisdiction.","module":2,"topic":"M2:Government Grants"},{"q":"Government Grants: What should be reviewed before accepting a government award?","opts":["Public award obligations","Official notice","Applicant eligibility","Authorized registration"],"correct":0,"exp":"Public award obligations may include reporting, procurement and financial rules specified in the agreement and applicable requirements.","module":2,"topic":"M2:Government Grants"}]},
  {"key":"M2:NGO Grants","rows":[{"q":"NGO Grants: What should be verified before assuming that any NGO offers grants?","opts":["Program alignment","Partner capacity","Agreed obligations","Grantmaking role"],"correct":3,"exp":"An NGO may implement programs without being a grantmaker; confirm its actual funding role.","module":2,"topic":"M2:NGO Grants"},{"q":"NGO Grants: What should guide a proposal to an NGO funding program?","opts":["Grantmaking role","Program alignment","Partner capacity","Agreed obligations"],"correct":1,"exp":"Program alignment connects the proposed work with the NGO's stated funding objectives.","module":2,"topic":"M2:NGO Grants"},{"q":"NGO Grants: What helps an NGO assess whether a potential implementing partner can deliver?","opts":["Partner capacity","Grantmaking role","Program alignment","Agreed obligations"],"correct":0,"exp":"Partner capacity includes relevant experience, resources, governance and controls supported by evidence.","module":2,"topic":"M2:NGO Grants"},{"q":"NGO Grants: What should govern work after funding is accepted?","opts":["Agreed obligations","Grantmaking role","Program alignment","Partner capacity"],"correct":0,"exp":"Agreed obligations define scope, funds, reporting and responsibilities under the actual award.","module":2,"topic":"M2:NGO Grants"}]},
  {"key":"M2:Foundation Grants","rows":[{"q":"Foundation Grants: What should a researcher examine before approaching a foundation?","opts":["Application route","Eligibility condition","Charitable priority","Grant history evidence"],"correct":2,"exp":"Charitable priorities explain the purposes and beneficiaries the foundation intends to support.","module":2,"topic":"M2:Foundation Grants"},{"q":"Foundation Grants: What should determine whether to submit a letter, concept note or full application?","opts":["Charitable priority","Eligibility condition","Grant history evidence","Application route"],"correct":3,"exp":"Follow the foundation's current application route, including whether unsolicited applications are accepted.","module":2,"topic":"M2:Foundation Grants"},{"q":"Foundation Grants: What must still be checked when the proposed cause matches the foundation's interests?","opts":["Charitable priority","Eligibility condition","Application route","Grant history evidence"],"correct":1,"exp":"Eligibility can include applicant type, geography and other conditions beyond thematic fit.","module":2,"topic":"M2:Foundation Grants"},{"q":"Foundation Grants: What can past awards help a researcher understand?","opts":["Charitable priority","Grant history evidence","Application route","Eligibility condition"],"correct":1,"exp":"Grant history offers evidence of past patterns but does not guarantee current priorities or future approval.","module":2,"topic":"M2:Foundation Grants"}]},
  {"key":"M2:Corporate Grants","rows":[{"q":"Corporate Grants: What should shape a request to a corporate giving program?","opts":["Geographic relevance","Verified program","Giving priorities","Responsible recognition"],"correct":2,"exp":"The company's actual giving priorities determine whether the proposed purpose fits.","module":2,"topic":"M2:Corporate Grants"},{"q":"Corporate Grants: What should be checked when a corporate program serves selected communities?","opts":["Geographic relevance","Giving priorities","Verified program","Responsible recognition"],"correct":0,"exp":"Geographic relevance may depend on where the company operates or the program's explicit scope.","module":2,"topic":"M2:Corporate Grants"},{"q":"Corporate Grants: What reduces the risk of responding to a fraudulent funding invitation?","opts":["Giving priorities","Geographic relevance","Responsible recognition","Verified program"],"correct":3,"exp":"Verify the program through an authoritative company channel before sharing information or paying anything.","module":2,"topic":"M2:Corporate Grants"},{"q":"Corporate Grants: What should be agreed before promising publicity for a corporate contribution?","opts":["Giving priorities","Geographic relevance","Responsible recognition","Verified program"],"correct":2,"exp":"Recognition must fit authorization, donor terms and ethical responsibilities rather than making unsupported promises.","module":2,"topic":"M2:Corporate Grants"}]},
  {"key":"M2:International Development Grants","rows":[{"q":"International Development Grants: What should connect an international development proposal with the funding program?","opts":["Country and applicant scope","Local partnership","Context-sensitive design","Development objective"],"correct":3,"exp":"A development objective identifies the result the program intends to support.","module":2,"topic":"M2:International Development Grants"},{"q":"International Development Grants: What should be checked before assuming an overseas opportunity is open locally?","opts":["Development objective","Country and applicant scope","Local partnership","Context-sensitive design"],"correct":1,"exp":"Country and applicant scope can restrict eligible locations, organizations or partnerships.","module":2,"topic":"M2:International Development Grants"},{"q":"International Development Grants: What can support delivery when an applicant lacks local knowledge?","opts":["Local partnership","Development objective","Country and applicant scope","Context-sensitive design"],"correct":0,"exp":"A suitable local partnership combines relevant capability and context with clear, authorized responsibilities.","module":2,"topic":"M2:International Development Grants"},{"q":"International Development Grants: What should avoid imposing a generic intervention without community input?","opts":["Development objective","Country and applicant scope","Local partnership","Context-sensitive design"],"correct":3,"exp":"Context-sensitive design uses local evidence, consultation and feasible delivery arrangements.","module":2,"topic":"M2:International Development Grants"}]},
  {"key":"M2:Small Business Grants","rows":[{"q":"Small Business Grants: What should be checked before a business prepares a grant application?","opts":["Program purpose","Business eligibility","Permitted costs","Verified opportunity"],"correct":1,"exp":"Eligibility may depend on location, business type, stage or other specific conditions.","module":2,"topic":"M2:Small Business Grants"},{"q":"Small Business Grants: What distinguishes a suitable small-business opportunity from an unrelated listing?","opts":["Business eligibility","Permitted costs","Program purpose","Verified opportunity"],"correct":2,"exp":"The proposed business activity must fit the program's actual purpose and supported outcomes.","module":2,"topic":"M2:Small Business Grants"},{"q":"Small Business Grants: What determines whether equipment or wages can be included in the request?","opts":["Permitted costs","Business eligibility","Program purpose","Verified opportunity"],"correct":0,"exp":"Permitted costs are established by the specific opportunity and award conditions, not by assuming all business expenses qualify.","module":2,"topic":"M2:Small Business Grants"},{"q":"Small Business Grants: What should a founder do with a message promising guaranteed grant approval?","opts":["Verified opportunity","Business eligibility","Program purpose","Permitted costs"],"correct":0,"exp":"Verify the opportunity and be cautious of unsupported guarantees; legitimate eligibility does not ensure selection.","module":2,"topic":"M2:Small Business Grants"}]},
  {"key":"M2:Grant Life Cycle","rows":[{"q":"Grant Life Cycle: Which stage establishes whether an opportunity is worth pursuing?","opts":["Application development","Award implementation","Opportunity screening","Closeout and learning"],"correct":2,"exp":"Screening checks fit, eligibility, deadline, capacity and likely preparation effort.","module":2,"topic":"M2:Grant Life Cycle"},{"q":"Grant Life Cycle: Which stage prepares narrative, budget and required attachments?","opts":["Opportunity screening","Application development","Award implementation","Closeout and learning"],"correct":1,"exp":"Application development assembles a coherent, compliant response to the actual opportunity.","module":2,"topic":"M2:Grant Life Cycle"},{"q":"Grant Life Cycle: Which stage carries out the authorized activities and reporting obligations?","opts":["Award implementation","Opportunity screening","Application development","Closeout and learning"],"correct":0,"exp":"Award implementation follows accepted terms and tracks funds, delivery and risks.","module":2,"topic":"M2:Grant Life Cycle"},{"q":"Grant Life Cycle: Which stage completes final obligations and records lessons?","opts":["Opportunity screening","Closeout and learning","Application development","Award implementation"],"correct":1,"exp":"Closeout follows the funder's requirements and includes appropriate final records and learning.","module":2,"topic":"M2:Grant Life Cycle"}]},
  {"key":"M2:Grant Terminology","rows":[{"q":"Grant Terminology: What term describes the organization requesting funding?","opts":["Grantee","Deliverable","Matching contribution","Applicant"],"correct":3,"exp":"The applicant is the entity applying; applying does not establish that an award exists.","module":2,"topic":"M2:Grant Terminology"},{"q":"Grant Terminology: What term describes the entity that receives an accepted grant award?","opts":["Grantee","Applicant","Deliverable","Matching contribution"],"correct":0,"exp":"The grantee has responsibilities under the award's actual terms.","module":2,"topic":"M2:Grant Terminology"},{"q":"Grant Terminology: What term describes a specified item or result to be supplied under the project?","opts":["Applicant","Grantee","Deliverable","Matching contribution"],"correct":2,"exp":"A deliverable is a defined output or requirement whose completion can be checked.","module":2,"topic":"M2:Grant Terminology"},{"q":"Grant Terminology: What term describes required support contributed in addition to the grant request?","opts":["Applicant","Matching contribution","Grantee","Deliverable"],"correct":1,"exp":"A matching contribution must meet the donor's rules for eligibility, valuation and documentation.","module":2,"topic":"M2:Grant Terminology"}]},
  {"key":"M3:Researching Donors","rows":[{"q":"Researching Donors: What should donor research examine before drafting an appeal?","opts":["Award pattern","Priority research","Current criteria","Fit record"],"correct":1,"exp":"Priority research identifies the causes, outcomes and beneficiaries the donor is currently interested in.","module":3,"topic":"M3:Researching Donors"},{"q":"Researching Donors: What can previous grants reveal when interpreted cautiously?","opts":["Priority research","Current criteria","Award pattern","Fit record"],"correct":2,"exp":"Award patterns show historical behavior but are not a guarantee of current interest or future funding.","module":3,"topic":"M3:Researching Donors"},{"q":"Researching Donors: What should be verified after finding an encouraging older listing?","opts":["Priority research","Award pattern","Current criteria","Fit record"],"correct":2,"exp":"Current criteria and deadlines must be checked with the authoritative donor source.","module":3,"topic":"M3:Researching Donors"},{"q":"Researching Donors: What should summarize a researcher's recommendation to pursue or decline an opportunity?","opts":["Priority research","Award pattern","Current criteria","Fit record"],"correct":3,"exp":"A fit record states evidence, constraints, eligibility and the reasoning behind the recommendation.","module":3,"topic":"M3:Researching Donors"}]},
  {"key":"M3:Grant Databases","rows":[{"q":"Grant Databases: What is the primary role of a grant database?","opts":["Discovery tool","Search filter","Authoritative verification","Research record"],"correct":0,"exp":"A database helps discover opportunities; it does not replace a funder's current instructions.","module":3,"topic":"M3:Grant Databases"},{"q":"Grant Databases: What helps narrow results to a relevant topic, geography or applicant type?","opts":["Discovery tool","Authoritative verification","Search filter","Research record"],"correct":2,"exp":"Search filters reduce irrelevant listings, while their accuracy and scope still need checking.","module":3,"topic":"M3:Grant Databases"},{"q":"Grant Databases: What should follow finding a potentially suitable listing?","opts":["Authoritative verification","Discovery tool","Search filter","Research record"],"correct":0,"exp":"Verify its existence, deadline and conditions with the funder or official portal.","module":3,"topic":"M3:Grant Databases"},{"q":"Grant Databases: What prevents a team from losing the evidence behind its shortlist?","opts":["Discovery tool","Search filter","Authoritative verification","Research record"],"correct":3,"exp":"A research record captures sources, dates, criteria and the current status of each opportunity.","module":3,"topic":"M3:Grant Databases"}]},
  {"key":"M3:Foundation Directories","rows":[{"q":"Foundation Directories: What information helps describe a foundation's purposes and organizational identity?","opts":["Giving history","Contact route","Profile currency","Foundation profile"],"correct":3,"exp":"A profile provides background to screen relevance but must be assessed for reliability.","module":3,"topic":"M3:Foundation Directories"},{"q":"Foundation Directories: What helps identify the kinds of causes previously funded?","opts":["Giving history","Foundation profile","Contact route","Profile currency"],"correct":0,"exp":"Giving history shows past awards and their context without promising future availability.","module":3,"topic":"M3:Foundation Directories"},{"q":"Foundation Directories: What should determine how an applicant may approach the foundation?","opts":["Contact route","Foundation profile","Giving history","Profile currency"],"correct":0,"exp":"Use the foundation's permitted contact and application route rather than an assumed unsolicited submission.","module":3,"topic":"M3:Foundation Directories"},{"q":"Foundation Directories: What should be checked before relying on an old directory entry?","opts":["Profile currency","Foundation profile","Giving history","Contact route"],"correct":0,"exp":"Profile currency concerns whether the information still reflects the foundation's current position.","module":3,"topic":"M3:Foundation Directories"}]},
  {"key":"M3:Government Funding Portals","rows":[{"q":"Government Funding Portals: What should be checked before entering organizational information into a government-grant site?","opts":["Opportunity instructions","Account authorization","Submission status","Official domain verification"],"correct":3,"exp":"Verify the official portal through an authoritative government source rather than a lookalike link.","module":3,"topic":"M3:Government Funding Portals"},{"q":"Government Funding Portals: What should determine the required application forms and attachments?","opts":["Official domain verification","Opportunity instructions","Account authorization","Submission status"],"correct":1,"exp":"The specific opportunity instructions define the actual submission requirements.","module":3,"topic":"M3:Government Funding Portals"},{"q":"Government Funding Portals: What should be established before someone submits on an organization's behalf?","opts":["Official domain verification","Account authorization","Opportunity instructions","Submission status"],"correct":1,"exp":"Account authorization confirms the person is permitted to prepare or submit under the applicable process.","module":3,"topic":"M3:Government Funding Portals"},{"q":"Government Funding Portals: What should an applicant inspect after sending an application?","opts":["Submission status","Official domain verification","Opportunity instructions","Account authorization"],"correct":0,"exp":"Submission status and acknowledgments establish whether the portal received or validated the submission as required; they do not prove an award.","module":3,"topic":"M3:Government Funding Portals"}]},
  {"key":"M3:Corporate Giving Programs","rows":[{"q":"Corporate Giving Programs: What should a corporate funding request connect with?","opts":["Community priority","Program conditions","Company verification","Relationship suitability"],"correct":0,"exp":"A community priority identifies the cause or location the actual program supports.","module":3,"topic":"M3:Corporate Giving Programs"},{"q":"Corporate Giving Programs: What determines whether a corporate program accepts the proposed applicant and activity?","opts":["Community priority","Company verification","Program conditions","Relationship suitability"],"correct":2,"exp":"Program conditions establish eligibility, supported costs and the application route.","module":3,"topic":"M3:Corporate Giving Programs"},{"q":"Corporate Giving Programs: What should precede responding to a funding offer using a company's name?","opts":["Community priority","Company verification","Program conditions","Relationship suitability"],"correct":1,"exp":"Verify the offer through an authoritative company contact or published program channel.","module":3,"topic":"M3:Corporate Giving Programs"},{"q":"Corporate Giving Programs: What should an organization consider before accepting corporate support?","opts":["Community priority","Program conditions","Company verification","Relationship suitability"],"correct":3,"exp":"Relationship suitability includes mission alignment, restrictions, reputational effects and feasible obligations.","module":3,"topic":"M3:Corporate Giving Programs"}]},
  {"key":"M3:Reading Grant Guidelines","rows":[{"q":"Reading Grant Guidelines: What section explains what the funder intends the opportunity to achieve?","opts":["Eligibility rules","Evaluation criteria","Purpose and scope","Submission instructions"],"correct":2,"exp":"Purpose and scope identify the supported goals, activities and boundaries.","module":3,"topic":"M3:Reading Grant Guidelines"},{"q":"Reading Grant Guidelines: What section establishes who and what may qualify?","opts":["Eligibility rules","Purpose and scope","Evaluation criteria","Submission instructions"],"correct":0,"exp":"Eligibility rules can concern applicant type, location, activities and other mandatory conditions.","module":3,"topic":"M3:Reading Grant Guidelines"},{"q":"Reading Grant Guidelines: What explains how a compliant proposal will be assessed?","opts":["Purpose and scope","Eligibility rules","Evaluation criteria","Submission instructions"],"correct":2,"exp":"Evaluation criteria guide what evidence and reasoning the application should demonstrate.","module":3,"topic":"M3:Reading Grant Guidelines"},{"q":"Reading Grant Guidelines: What should govern format, attachments and delivery of the application?","opts":["Purpose and scope","Eligibility rules","Submission instructions","Evaluation criteria"],"correct":2,"exp":"Submission instructions define the actual process, limits and deadline conditions.","module":3,"topic":"M3:Reading Grant Guidelines"}]},
  {"key":"M3:Eligibility Requirements","rows":[{"q":"Eligibility Requirements: What should be verified about the applying entity?","opts":["Geographic condition","Applicant status","Activity fit","Mandatory evidence"],"correct":1,"exp":"Applicant status must match the opportunity's permitted organization or individual categories.","module":3,"topic":"M3:Eligibility Requirements"},{"q":"Eligibility Requirements: What should be checked when a funder limits work to selected locations?","opts":["Applicant status","Activity fit","Geographic condition","Mandatory evidence"],"correct":2,"exp":"A geographic condition may apply to the applicant, beneficiaries or implementation site.","module":3,"topic":"M3:Eligibility Requirements"},{"q":"Eligibility Requirements: What should be checked about the proposed intervention?","opts":["Applicant status","Geographic condition","Mandatory evidence","Activity fit"],"correct":3,"exp":"Activity fit confirms that the opportunity supports the intended work and excludes prohibited activities.","module":3,"topic":"M3:Eligibility Requirements"},{"q":"Eligibility Requirements: What establishes a required eligibility claim for the reviewer?","opts":["Applicant status","Geographic condition","Activity fit","Mandatory evidence"],"correct":3,"exp":"Mandatory evidence supplies the documents or information the funder actually requires; an unsupported assertion is insufficient.","module":3,"topic":"M3:Eligibility Requirements"}]},
  {"key":"M3:Grant Opportunity Assessment","rows":[{"q":"Grant Opportunity Assessment: What determines whether the opportunity advances the organization's mission?","opts":["Delivery feasibility","Strategic fit","Preparation effort","Pursuit decision"],"correct":1,"exp":"Strategic fit connects funder priorities with the organization's real purpose and capabilities.","module":3,"topic":"M3:Grant Opportunity Assessment"},{"q":"Grant Opportunity Assessment: What should be checked before promising the proposed project?","opts":["Strategic fit","Preparation effort","Delivery feasibility","Pursuit decision"],"correct":2,"exp":"Delivery feasibility examines capacity, resources, obligations and time.","module":3,"topic":"M3:Grant Opportunity Assessment"},{"q":"Grant Opportunity Assessment: What should a team estimate before starting a demanding application?","opts":["Preparation effort","Strategic fit","Delivery feasibility","Pursuit decision"],"correct":0,"exp":"Preparation effort includes staff time, evidence, documents, approvals and submission work.","module":3,"topic":"M3:Grant Opportunity Assessment"},{"q":"Grant Opportunity Assessment: What should follow comparing fit, feasibility and effort?","opts":["Strategic fit","Delivery feasibility","Pursuit decision","Preparation effort"],"correct":2,"exp":"A pursuit decision documents whether to proceed, defer or decline based on evidence.","module":3,"topic":"M3:Grant Opportunity Assessment"}]},
  {"key":"M3:Building a Funding Pipeline","rows":[{"q":"Building a Funding Pipeline: What lets a team distinguish discovered prospects from submitted applications?","opts":["Responsible owner","Next action","Opportunity stage","Portfolio balance"],"correct":2,"exp":"Opportunity stages provide consistent status definitions across the pipeline.","module":3,"topic":"M3:Building a Funding Pipeline"},{"q":"Building a Funding Pipeline: What prevents an application deadline from belonging vaguely to everyone?","opts":["Responsible owner","Opportunity stage","Next action","Portfolio balance"],"correct":0,"exp":"A responsible owner coordinates the next action and required approvals.","module":3,"topic":"M3:Building a Funding Pipeline"},{"q":"Building a Funding Pipeline: What keeps an opportunity moving beyond merely appearing on a list?","opts":["Opportunity stage","Next action","Responsible owner","Portfolio balance"],"correct":1,"exp":"A next action records the specific task, owner and date.","module":3,"topic":"M3:Building a Funding Pipeline"},{"q":"Building a Funding Pipeline: What reduces dependence on a single unconfirmed funding source?","opts":["Opportunity stage","Responsible owner","Portfolio balance","Next action"],"correct":2,"exp":"Portfolio balance considers a feasible range of aligned prospects without assuming every opportunity will succeed.","module":3,"topic":"M3:Building a Funding Pipeline"}]},
  {"key":"M4:Mission & Vision","rows":[{"q":"Mission & Vision: What explains whom the organization serves and its present purpose?","opts":["Mission","Vision","Program alignment","Strategic consistency"],"correct":0,"exp":"A mission describes the organization's role and intended value.","module":4,"topic":"M4:Mission & Vision"},{"q":"Mission & Vision: What expresses the future condition the organization aims to help create?","opts":["Mission","Program alignment","Vision","Strategic consistency"],"correct":2,"exp":"A vision articulates direction without substituting for a feasible operating plan.","module":4,"topic":"M4:Mission & Vision"},{"q":"Mission & Vision: What should be established before pursuing funding for a new activity?","opts":["Mission","Program alignment","Vision","Strategic consistency"],"correct":1,"exp":"Program alignment checks that the activity fits the organization's authorized purpose.","module":4,"topic":"M4:Mission & Vision"},{"q":"Mission & Vision: What prevents an organization from changing its purpose simply to chase unrelated grants?","opts":["Mission","Vision","Strategic consistency","Program alignment"],"correct":2,"exp":"Strategic consistency connects funding choices with mission, capability and agreed priorities.","module":4,"topic":"M4:Mission & Vision"}]},
  {"key":"M4:Organizational Capacity","rows":[{"q":"Organizational Capacity: What evidence supports a claim that the organization has delivered similar work?","opts":["People and skills","Operating systems","Relevant experience","Delivery constraints"],"correct":2,"exp":"Relevant experience uses verified examples and results, clearly distinguishing the organization's role.","module":4,"topic":"M4:Organizational Capacity"},{"q":"Organizational Capacity: What should be assessed before assigning a new program to existing staff?","opts":["People and skills","Relevant experience","Operating systems","Delivery constraints"],"correct":0,"exp":"People and skills must include appropriate capability and realistic available capacity.","module":4,"topic":"M4:Organizational Capacity"},{"q":"Organizational Capacity: What supports reliable finance, scheduling and reporting?","opts":["Relevant experience","People and skills","Operating systems","Delivery constraints"],"correct":2,"exp":"Operating systems define usable processes, responsibilities and controls.","module":4,"topic":"M4:Organizational Capacity"},{"q":"Organizational Capacity: What should be disclosed if a proposed activity depends on an unconfirmed partner?","opts":["Delivery constraints","Relevant experience","People and skills","Operating systems"],"correct":0,"exp":"Delivery constraints and assumptions must be visible so the proposal does not overstate readiness.","module":4,"topic":"M4:Organizational Capacity"}]},
  {"key":"M4:Governance Structure","rows":[{"q":"Governance Structure: What establishes who may approve a grant application or agreement?","opts":["Oversight responsibility","Conflict safeguards","Accountable records","Decision authority"],"correct":3,"exp":"Decision authority follows the organization's actual governance and delegated powers.","module":4,"topic":"M4:Governance Structure"},{"q":"Governance Structure: What provides review of management decisions and organizational responsibilities?","opts":["Decision authority","Conflict safeguards","Accountable records","Oversight responsibility"],"correct":3,"exp":"Oversight responsibility should be clear and suitable for the organization's structure.","module":4,"topic":"M4:Governance Structure"},{"q":"Governance Structure: What should address a board member's personal interest in a proposed supplier?","opts":["Decision authority","Oversight responsibility","Accountable records","Conflict safeguards"],"correct":3,"exp":"Conflict safeguards use disclosure and appropriate independent review or recusal under applicable arrangements.","module":4,"topic":"M4:Governance Structure"},{"q":"Governance Structure: What supports later review of a significant governance decision?","opts":["Decision authority","Oversight responsibility","Conflict safeguards","Accountable records"],"correct":3,"exp":"Accountable records document the decision, rationale, authority and follow-up accurately.","module":4,"topic":"M4:Governance Structure"}]},
  {"key":"M4:Financial Readiness","rows":[{"q":"Financial Readiness: What should support the financial figures supplied with an application?","opts":["Reliable accounts","Cash timing plan","Spending controls","Reporting capability"],"correct":0,"exp":"Reliable accounts use consistent records and verifiable definitions rather than invented totals.","module":4,"topic":"M4:Financial Readiness"},{"q":"Financial Readiness: What should be reviewed if grant payments arrive after costs must be paid?","opts":["Reliable accounts","Spending controls","Reporting capability","Cash timing plan"],"correct":3,"exp":"A cash timing plan checks whether obligations can be met during reimbursement or delayed-payment periods.","module":4,"topic":"M4:Financial Readiness"},{"q":"Financial Readiness: What should prevent unauthorized use of restricted funds?","opts":["Reliable accounts","Cash timing plan","Reporting capability","Spending controls"],"correct":3,"exp":"Spending controls connect approval and expenditure with permitted purposes and the award terms.","module":4,"topic":"M4:Financial Readiness"},{"q":"Financial Readiness: What must an organization be able to do after receiving a grant?","opts":["Reliable accounts","Reporting capability","Cash timing plan","Spending controls"],"correct":1,"exp":"Reporting capability includes appropriate tracking, documentation and timely required statements.","module":4,"topic":"M4:Financial Readiness"}]},
  {"key":"M4:Registration & Legal Documents","rows":[{"q":"Registration & Legal Documents: What should be checked about an applicant's legal identity?","opts":["Current status","Applicable registration","Authorized signatory","Verified requirement"],"correct":1,"exp":"Applicable registration depends on local rules, the entity type and the opportunity's conditions.","module":4,"topic":"M4:Registration & Legal Documents"},{"q":"Registration & Legal Documents: What should be verified before attaching a registration document?","opts":["Applicable registration","Authorized signatory","Current status","Verified requirement"],"correct":2,"exp":"Current status and document validity must reflect the actual entity and relevant period.","module":4,"topic":"M4:Registration & Legal Documents"},{"q":"Registration & Legal Documents: What should establish who may sign a required declaration?","opts":["Applicable registration","Current status","Verified requirement","Authorized signatory"],"correct":3,"exp":"An authorized signatory has the relevant authority under the entity's arrangements and the application process.","module":4,"topic":"M4:Registration & Legal Documents"},{"q":"Registration & Legal Documents: What prevents treating one country's document list as a universal checklist?","opts":["Applicable registration","Verified requirement","Current status","Authorized signatory"],"correct":1,"exp":"Verify the specific funder and jurisdiction requirements instead of copying an unrelated application's list.","module":4,"topic":"M4:Registration & Legal Documents"}]},
  {"key":"M4:Organizational Profile","rows":[{"q":"Organizational Profile: What should introduce an organization clearly to a potential funder?","opts":["Track record","Identity and purpose","Capabilities","Verified contact"],"correct":1,"exp":"Identity and purpose explain what the organization is and whom it serves.","module":4,"topic":"M4:Organizational Profile"},{"q":"Organizational Profile: What supports an organization's claim of previous achievement?","opts":["Identity and purpose","Track record","Capabilities","Verified contact"],"correct":1,"exp":"A track record uses accurate examples and results with relevant context and sources.","module":4,"topic":"M4:Organizational Profile"},{"q":"Organizational Profile: What should explain why the organization can deliver the proposed work?","opts":["Identity and purpose","Capabilities","Track record","Verified contact"],"correct":1,"exp":"Capabilities include suitable people, systems, partnerships and resources supported by evidence.","module":4,"topic":"M4:Organizational Profile"},{"q":"Organizational Profile: What enables the reviewer to reach the correct responsible organization?","opts":["Verified contact","Identity and purpose","Track record","Capabilities"],"correct":0,"exp":"Verified contact information and current organizational details reduce avoidable confusion.","module":4,"topic":"M4:Organizational Profile"}]},
  {"key":"M4:Strategic Planning","rows":[{"q":"Strategic Planning: What should precede selecting new funding priorities?","opts":["Priority choices","Resource alignment","Current diagnosis","Review process"],"correct":2,"exp":"Diagnosis examines needs, capabilities, evidence and constraints in the organization's context.","module":4,"topic":"M4:Strategic Planning"},{"q":"Strategic Planning: What helps decide which opportunities to pursue and which to decline?","opts":["Current diagnosis","Priority choices","Resource alignment","Review process"],"correct":1,"exp":"Priority choices make mission-related trade-offs rather than treating every grant as suitable.","module":4,"topic":"M4:Strategic Planning"},{"q":"Strategic Planning: What connects a chosen initiative with feasible delivery?","opts":["Resource alignment","Current diagnosis","Priority choices","Review process"],"correct":0,"exp":"Resource alignment checks people, funds, systems and timing needed to act.","module":4,"topic":"M4:Strategic Planning"},{"q":"Strategic Planning: What keeps the strategy useful when funding or community conditions change?","opts":["Current diagnosis","Review process","Priority choices","Resource alignment"],"correct":1,"exp":"A review process examines new evidence and adjusts priorities and plans when appropriate.","module":4,"topic":"M4:Strategic Planning"}]},
  {"key":"M4:Preparing Supporting Documents","rows":[{"q":"Preparing Supporting Documents: What should identify every document needed for a specific application?","opts":["Document owner","Consistency check","Secure version control","Requirement checklist"],"correct":3,"exp":"A checklist is built from the actual instructions and includes format, validity and deadline conditions.","module":4,"topic":"M4:Preparing Supporting Documents"},{"q":"Preparing Supporting Documents: What makes collecting a required audit or partner letter accountable?","opts":["Requirement checklist","Consistency check","Secure version control","Document owner"],"correct":3,"exp":"A document owner is responsible for obtaining the correct authorized material on time.","module":4,"topic":"M4:Preparing Supporting Documents"},{"q":"Preparing Supporting Documents: What should be checked when documents use different budget totals or organization names?","opts":["Requirement checklist","Consistency check","Document owner","Secure version control"],"correct":1,"exp":"Consistency checks reconcile discrepancies before submission rather than expecting reviewers to infer the intended facts.","module":4,"topic":"M4:Preparing Supporting Documents"},{"q":"Preparing Supporting Documents: What protects a submission from using an outdated or unauthorized file?","opts":["Secure version control","Requirement checklist","Document owner","Consistency check"],"correct":0,"exp":"Secure version control identifies the approved current copy and restricts inappropriate access.","module":4,"topic":"M4:Preparing Supporting Documents"}]},
  {"key":"M5:Identifying Community Problems","rows":[{"q":"Identifying Community Problems: What should a needs inquiry identify beyond a broad issue label?","opts":["Observed condition","Affected group","Evidence source","Priority rationale"],"correct":1,"exp":"An affected group defines whose situation the project seeks to improve without assuming everyone has the same needs.","module":5,"topic":"M5:Identifying Community Problems"},{"q":"Identifying Community Problems: What should describe the problem in a form that can be investigated?","opts":["Affected group","Evidence source","Priority rationale","Observed condition"],"correct":3,"exp":"An observed condition states what is happening and distinguishes evidence from assumption.","module":5,"topic":"M5:Identifying Community Problems"},{"q":"Identifying Community Problems: What should support a claim about the scale of the problem?","opts":["Evidence source","Affected group","Observed condition","Priority rationale"],"correct":0,"exp":"An evidence source provides relevant, reliable information with its period and limitations.","module":5,"topic":"M5:Identifying Community Problems"},{"q":"Identifying Community Problems: What should explain why this problem is selected over another?","opts":["Affected group","Observed condition","Evidence source","Priority rationale"],"correct":3,"exp":"Priority rationale considers community input, severity, feasibility and mission fit rather than the writer's preference alone.","module":5,"topic":"M5:Identifying Community Problems"}]},
  {"key":"M5:Conducting Research","rows":[{"q":"Conducting Research: What should guide the collection of information?","opts":["Research question","Suitable method","Source assessment","Transparent limitation"],"correct":0,"exp":"A research question states what needs to be learned to support a decision.","module":5,"topic":"M5:Conducting Research"},{"q":"Conducting Research: What should be chosen to answer the question responsibly?","opts":["Research question","Source assessment","Transparent limitation","Suitable method"],"correct":3,"exp":"A suitable method matches the question, context, resources and ethical requirements.","module":5,"topic":"M5:Conducting Research"},{"q":"Conducting Research: What should precede using a published statistic in a proposal?","opts":["Research question","Suitable method","Source assessment","Transparent limitation"],"correct":2,"exp":"Assess its source, definitions, date, relevance and reliability before drawing conclusions.","module":5,"topic":"M5:Conducting Research"},{"q":"Conducting Research: What should a report disclose about a small or incomplete sample?","opts":["Research question","Suitable method","Source assessment","Transparent limitation"],"correct":3,"exp":"Transparent limitations prevent an observation from being overstated as representing every beneficiary.","module":5,"topic":"M5:Conducting Research"}]},
  {"key":"M5:Collecting Data","rows":[{"q":"Collecting Data: What should determine which data a project collects?","opts":["Consistent instrument","Appropriate consent","Defined information need","Quality check"],"correct":2,"exp":"A defined information need connects collection with the question or indicator rather than gathering unnecessary personal details.","module":5,"topic":"M5:Collecting Data"},{"q":"Collecting Data: What helps interviewers ask comparable questions?","opts":["Defined information need","Appropriate consent","Consistent instrument","Quality check"],"correct":2,"exp":"A consistent instrument provides suitable questions, definitions and recording instructions.","module":5,"topic":"M5:Collecting Data"},{"q":"Collecting Data: What should be checked before collecting identifiable community information?","opts":["Defined information need","Consistent instrument","Quality check","Appropriate consent"],"correct":3,"exp":"Consent and safeguarding arrangements must fit the participants, purpose and applicable requirements.","module":5,"topic":"M5:Collecting Data"},{"q":"Collecting Data: What detects incomplete entries or inconsistent units?","opts":["Defined information need","Quality check","Consistent instrument","Appropriate consent"],"correct":1,"exp":"Quality checks examine the data before it is interpreted or reported.","module":5,"topic":"M5:Collecting Data"}]},
  {"key":"M5:Stakeholder Consultation","rows":[{"q":"Stakeholder Consultation: What should consultation seek when some affected groups are usually absent?","opts":["Accessible engagement","Inclusive participation","Recorded perspectives","Design response"],"correct":1,"exp":"Inclusive participation makes relevant voices visible rather than assuming the most vocal group represents everyone.","module":5,"topic":"M5:Stakeholder Consultation"},{"q":"Stakeholder Consultation: What helps people contribute despite language, travel or connectivity barriers?","opts":["Inclusive participation","Recorded perspectives","Accessible engagement","Design response"],"correct":2,"exp":"Accessible engagement chooses suitable methods and arrangements for the participants.","module":5,"topic":"M5:Stakeholder Consultation"},{"q":"Stakeholder Consultation: What should be captured after a consultation?","opts":["Inclusive participation","Recorded perspectives","Accessible engagement","Design response"],"correct":1,"exp":"Record relevant perspectives accurately while protecting personal information and noting disagreements.","module":5,"topic":"M5:Stakeholder Consultation"},{"q":"Stakeholder Consultation: What shows that consultation affected the proposal?","opts":["Inclusive participation","Accessible engagement","Recorded perspectives","Design response"],"correct":3,"exp":"A design response explains which choices changed and why, including concerns that remain unresolved.","module":5,"topic":"M5:Stakeholder Consultation"}]},
  {"key":"M5:Problem Statement","rows":[{"q":"Problem Statement: What makes a problem statement clearer than saying the community needs help?","opts":["Affected population","Evidence of scale","Consequences and context","Specific condition"],"correct":3,"exp":"A specific condition describes the issue precisely enough to investigate and address.","module":5,"topic":"M5:Problem Statement"},{"q":"Problem Statement: What defines whose situation the proposal concerns?","opts":["Specific condition","Evidence of scale","Affected population","Consequences and context"],"correct":2,"exp":"An affected population gives the relevant group and location without implying uniform experience.","module":5,"topic":"M5:Problem Statement"},{"q":"Problem Statement: What substantiates the size or frequency of the stated problem?","opts":["Evidence of scale","Specific condition","Affected population","Consequences and context"],"correct":0,"exp":"Evidence of scale uses credible, relevant data and states its period and limitations.","module":5,"topic":"M5:Problem Statement"},{"q":"Problem Statement: What explains why the problem matters and how it relates to the proposed response?","opts":["Specific condition","Affected population","Evidence of scale","Consequences and context"],"correct":3,"exp":"Consequences and context connect the condition with meaningful effects without inventing causal certainty.","module":5,"topic":"M5:Problem Statement"}]},
  {"key":"M5:Root Cause Analysis","rows":[{"q":"Root Cause Analysis: What should be agreed before discussing why a problem occurs?","opts":["Cause hypothesis","Evidence test","Problem definition","Intervention link"],"correct":2,"exp":"A clear problem definition prevents analysis from mixing several unrelated issues.","module":5,"topic":"M5:Root Cause Analysis"},{"q":"Root Cause Analysis: What is a proposed explanation that still needs verification?","opts":["Problem definition","Cause hypothesis","Evidence test","Intervention link"],"correct":1,"exp":"A cause hypothesis is an idea to test, not an established fact merely because it sounds plausible.","module":5,"topic":"M5:Root Cause Analysis"},{"q":"Root Cause Analysis: What should support accepting or rejecting a suspected cause?","opts":["Problem definition","Cause hypothesis","Intervention link","Evidence test"],"correct":3,"exp":"An evidence test considers relevant data and alternative explanations.","module":5,"topic":"M5:Root Cause Analysis"},{"q":"Root Cause Analysis: What should connect a verified cause with project design?","opts":["Problem definition","Cause hypothesis","Intervention link","Evidence test"],"correct":2,"exp":"The intervention link explains how the proposed activity is expected to influence the cause and under what assumptions.","module":5,"topic":"M5:Root Cause Analysis"}]},
  {"key":"M5:Target Beneficiaries","rows":[{"q":"Target Beneficiaries: What should explain who will be included in a project?","opts":["Selection criteria","Estimated reach","Access barriers","Safeguarding needs"],"correct":0,"exp":"Selection criteria should be relevant, transparent and consistent with the intended purpose and requirements.","module":5,"topic":"M5:Target Beneficiaries"},{"q":"Target Beneficiaries: What should be checked before claiming a project will serve 1,000 people?","opts":["Estimated reach","Selection criteria","Access barriers","Safeguarding needs"],"correct":0,"exp":"Estimated reach must be supported by delivery capacity and avoid double-counting the same people.","module":5,"topic":"M5:Target Beneficiaries"},{"q":"Target Beneficiaries: What should a designer examine when eligible people cannot readily participate?","opts":["Access barriers","Selection criteria","Estimated reach","Safeguarding needs"],"correct":0,"exp":"Access barriers may involve cost, timing, disability, language or other contextual obstacles.","module":5,"topic":"M5:Target Beneficiaries"},{"q":"Target Beneficiaries: What should be considered when the project involves children or vulnerable participants?","opts":["Safeguarding needs","Selection criteria","Estimated reach","Access barriers"],"correct":0,"exp":"Safeguarding needs require appropriate protections, consent arrangements and qualified oversight where relevant.","module":5,"topic":"M5:Target Beneficiaries"}]},
  {"key":"M5:Community Assessment Report","rows":[{"q":"Community Assessment Report: What should explain how the assessment obtained its information?","opts":["Findings and evidence","Methods account","Limitations","Priority recommendations"],"correct":1,"exp":"A methods account states sources, participants, procedures and relevant ethical arrangements.","module":5,"topic":"M5:Community Assessment Report"},{"q":"Community Assessment Report: What should support the report's description of community needs?","opts":["Methods account","Limitations","Findings and evidence","Priority recommendations"],"correct":2,"exp":"Findings are linked with evidence instead of replacing observations with unsupported conclusions.","module":5,"topic":"M5:Community Assessment Report"},{"q":"Community Assessment Report: What should disclose gaps in coverage or uncertain interpretation?","opts":["Methods account","Findings and evidence","Limitations","Priority recommendations"],"correct":2,"exp":"Limitations tell the reader what the evidence does and does not establish.","module":5,"topic":"M5:Community Assessment Report"},{"q":"Community Assessment Report: What should connect the assessment with feasible project choices?","opts":["Priority recommendations","Methods account","Findings and evidence","Limitations"],"correct":0,"exp":"Priority recommendations follow from the findings, community input and delivery constraints.","module":5,"topic":"M5:Community Assessment Report"}]},
  {"key":"M6:Anatomy of a Grant Proposal","rows":[{"q":"Anatomy of a Grant Proposal: Which part establishes the problem and the evidence for addressing it?","opts":["Design section","Budget section","Results section","Need section"],"correct":3,"exp":"The need section presents the relevant condition, affected group and supporting information.","module":6,"topic":"M6:Anatomy of a Grant Proposal"},{"q":"Anatomy of a Grant Proposal: Which part explains what the organization will do and how?","opts":["Need section","Design section","Budget section","Results section"],"correct":1,"exp":"The design section connects activities, capacity and timing with the proposed response.","module":6,"topic":"M6:Anatomy of a Grant Proposal"},{"q":"Anatomy of a Grant Proposal: Which part shows the resources and costs required?","opts":["Budget section","Need section","Design section","Results section"],"correct":0,"exp":"The budget section must be consistent with the activities and the funder's cost rules.","module":6,"topic":"M6:Anatomy of a Grant Proposal"},{"q":"Anatomy of a Grant Proposal: Which part explains the expected change and how it will be assessed?","opts":["Need section","Results section","Design section","Budget section"],"correct":1,"exp":"The results section links objectives, indicators and evaluation rather than counting activities alone.","module":6,"topic":"M6:Anatomy of a Grant Proposal"}]},
  {"key":"M6:Executive Summary","rows":[{"q":"Executive Summary: What should a concise proposal summary explain about the problem?","opts":["Proposed response","Funding request","Expected result","Purpose and need"],"correct":3,"exp":"Purpose and need give the essential reason for the project without introducing unsupported new claims.","module":6,"topic":"M6:Executive Summary"},{"q":"Executive Summary: What should the summary say about the intervention?","opts":["Purpose and need","Proposed response","Funding request","Expected result"],"correct":1,"exp":"A proposed response briefly explains the main activities and delivery approach.","module":6,"topic":"M6:Executive Summary"},{"q":"Executive Summary: What should be clear about the amount sought?","opts":["Funding request","Purpose and need","Proposed response","Expected result"],"correct":0,"exp":"The funding request should reconcile with the full budget and any required contribution.","module":6,"topic":"M6:Executive Summary"},{"q":"Executive Summary: What should connect the summary with the project's intended benefit?","opts":["Expected result","Purpose and need","Proposed response","Funding request"],"correct":0,"exp":"The expected result states the meaningful change sought and stays consistent with the proposal.","module":6,"topic":"M6:Executive Summary"}]},
  {"key":"M6:Organizational Background","rows":[{"q":"Organizational Background: What organizational information is most useful to a funder assessing fit?","opts":["Verified experience","Delivery capability","Relevant mission","Role clarity"],"correct":2,"exp":"A relevant mission connects the organization's purpose with the proposed intervention.","module":6,"topic":"M6:Organizational Background"},{"q":"Organizational Background: What should support a statement that the organization has a strong track record?","opts":["Relevant mission","Delivery capability","Role clarity","Verified experience"],"correct":3,"exp":"Verified experience uses accurate examples, roles and results rather than inflated claims.","module":6,"topic":"M6:Organizational Background"},{"q":"Organizational Background: What shows readiness to carry out the proposed activities?","opts":["Relevant mission","Verified experience","Delivery capability","Role clarity"],"correct":2,"exp":"Delivery capability includes suitable people, systems, partners and resources.","module":6,"topic":"M6:Organizational Background"},{"q":"Organizational Background: What should distinguish a partner's achievement from the applicant's own?","opts":["Relevant mission","Role clarity","Verified experience","Delivery capability"],"correct":1,"exp":"Role clarity accurately attributes responsibility and contribution rather than taking credit for all work.","module":6,"topic":"M6:Organizational Background"}]},
  {"key":"M6:Statement of Need","rows":[{"q":"Statement of Need: What should support a claim that a problem exists?","opts":["Beneficiary context","Relevant evidence","Problem significance","Response rationale"],"correct":1,"exp":"Relevant evidence uses current-enough, credible information and appropriate definitions.","module":6,"topic":"M6:Statement of Need"},{"q":"Statement of Need: What helps a reader understand how the problem affects the intended participants?","opts":["Relevant evidence","Problem significance","Beneficiary context","Response rationale"],"correct":2,"exp":"Beneficiary context describes actual circumstances and differences without stereotyping.","module":6,"topic":"M6:Statement of Need"},{"q":"Statement of Need: What explains why the issue warrants attention?","opts":["Relevant evidence","Beneficiary context","Problem significance","Response rationale"],"correct":2,"exp":"Problem significance considers severity, consequences and community priorities.","module":6,"topic":"M6:Statement of Need"},{"q":"Statement of Need: What should connect the need with the proposed project?","opts":["Response rationale","Relevant evidence","Beneficiary context","Problem significance"],"correct":0,"exp":"A response rationale explains why the chosen approach fits the evidence and what assumptions require checking.","module":6,"topic":"M6:Statement of Need"}]},
  {"key":"M6:Goals and Objectives","rows":[{"q":"Goals and Objectives: Which statement describes the wider change a project aims to support?","opts":["Broad goal","Specific objective","Outcome indicator","Time boundary"],"correct":0,"exp":"A broad goal gives direction but should not be mistaken for a directly verified project result.","module":6,"topic":"M6:Goals and Objectives"},{"q":"Goals and Objectives: Which statement sets a defined result that the project intends to achieve?","opts":["Specific objective","Broad goal","Outcome indicator","Time boundary"],"correct":0,"exp":"A specific objective identifies an assessable outcome for a relevant group and context.","module":6,"topic":"M6:Goals and Objectives"},{"q":"Goals and Objectives: What evidence shows progress toward the objective?","opts":["Broad goal","Outcome indicator","Specific objective","Time boundary"],"correct":1,"exp":"An outcome indicator is defined so the intended change can be examined consistently.","module":6,"topic":"M6:Goals and Objectives"},{"q":"Goals and Objectives: What should identify when the objective will be assessed?","opts":["Broad goal","Specific objective","Outcome indicator","Time boundary"],"correct":3,"exp":"A time boundary connects the expected result with a feasible review period.","module":6,"topic":"M6:Goals and Objectives"}]},
  {"key":"M6:Project Design","rows":[{"q":"Project Design: What explains how proposed activities are expected to produce results?","opts":["Delivery method","Intervention logic","Feasible resources","Assumptions and risks"],"correct":1,"exp":"Intervention logic connects actions, outputs and outcomes with a reasoned causal pathway.","module":6,"topic":"M6:Project Design"},{"q":"Project Design: What specifies how the activities will be implemented?","opts":["Intervention logic","Delivery method","Feasible resources","Assumptions and risks"],"correct":1,"exp":"A delivery method identifies suitable procedures, roles and participation arrangements.","module":6,"topic":"M6:Project Design"},{"q":"Project Design: What should be checked before promising the intervention at a given scale?","opts":["Intervention logic","Delivery method","Feasible resources","Assumptions and risks"],"correct":2,"exp":"Feasible resources include capacity, funds, materials and time consistent with the design.","module":6,"topic":"M6:Project Design"},{"q":"Project Design: What should make uncertain conditions visible?","opts":["Intervention logic","Delivery method","Feasible resources","Assumptions and risks"],"correct":3,"exp":"Assumptions and risks identify factors that could affect delivery or the intended results.","module":6,"topic":"M6:Project Design"}]},
  {"key":"M6:Activities and Timeline","rows":[{"q":"Activities and Timeline: What makes an activity more usable than a vague instruction to support the community?","opts":["Named responsibility","Sequence dependency","Defined activity","Milestone"],"correct":2,"exp":"A defined activity states the particular work and expected immediate deliverable.","module":6,"topic":"M6:Activities and Timeline"},{"q":"Activities and Timeline: What should identify who coordinates completion of the activity?","opts":["Defined activity","Named responsibility","Sequence dependency","Milestone"],"correct":1,"exp":"Named responsibility makes the task accountable and clarifies supporting roles.","module":6,"topic":"M6:Activities and Timeline"},{"q":"Activities and Timeline: What explains why training cannot start before materials are approved?","opts":["Defined activity","Named responsibility","Milestone","Sequence dependency"],"correct":3,"exp":"A sequence dependency records prerequisites that affect timing.","module":6,"topic":"M6:Activities and Timeline"},{"q":"Activities and Timeline: What marks a significant completion point in the work plan?","opts":["Defined activity","Milestone","Named responsibility","Sequence dependency"],"correct":1,"exp":"A milestone gives a clear point for checking progress and required decisions.","module":6,"topic":"M6:Activities and Timeline"}]},
  {"key":"M6:Expected Outcomes","rows":[{"q":"Expected Outcomes: What term describes delivering five workshops?","opts":["Output","Short-term outcome","Longer-term contribution","Verification plan"],"correct":0,"exp":"An output is an immediate product or service of the activity, not proof that participants' circumstances improved.","module":6,"topic":"M6:Expected Outcomes"},{"q":"Expected Outcomes: What term describes a verified improvement in participants' relevant skills?","opts":["Output","Longer-term contribution","Verification plan","Short-term outcome"],"correct":3,"exp":"A short-term outcome concerns change in capability or behavior beyond activity delivery.","module":6,"topic":"M6:Expected Outcomes"},{"q":"Expected Outcomes: What term describes a wider benefit the project may help support over time?","opts":["Output","Short-term outcome","Longer-term contribution","Verification plan"],"correct":2,"exp":"A longer-term contribution should be distinguished from a result caused solely and certainly by the project.","module":6,"topic":"M6:Expected Outcomes"},{"q":"Expected Outcomes: What should support a claim that the intended change occurred?","opts":["Output","Verification plan","Short-term outcome","Longer-term contribution"],"correct":1,"exp":"A verification plan defines suitable measures, sources, timing and limitations.","module":6,"topic":"M6:Expected Outcomes"}]},
  {"key":"M6:Sustainability Plan","rows":[{"q":"Sustainability Plan: What should sustainability planning seek after the initial grant period?","opts":["Operating responsibility","Resource pathway","Feasibility review","Continuing value"],"correct":3,"exp":"Continuing value concerns maintaining useful benefits rather than keeping every activity unchanged indefinitely.","module":6,"topic":"M6:Sustainability Plan"},{"q":"Sustainability Plan: What should identify who will maintain a supported service?","opts":["Continuing value","Resource pathway","Feasibility review","Operating responsibility"],"correct":3,"exp":"Operating responsibility must be agreed with capable, authorized people or organizations.","module":6,"topic":"M6:Sustainability Plan"},{"q":"Sustainability Plan: What should explain how continuing work could be financed or supported?","opts":["Continuing value","Operating responsibility","Resource pathway","Feasibility review"],"correct":2,"exp":"A resource pathway uses feasible funding and capacity assumptions rather than a guaranteed future grant.","module":6,"topic":"M6:Sustainability Plan"},{"q":"Sustainability Plan: What should be checked before promising indefinite continuation?","opts":["Continuing value","Operating responsibility","Resource pathway","Feasibility review"],"correct":3,"exp":"A feasibility review examines capacity, costs, risks and the evidence supporting the plan.","module":6,"topic":"M6:Sustainability Plan"}]},
  {"key":"M6:Proposal Checklist","rows":[{"q":"Proposal Checklist: What should confirm that every required section and attachment is present?","opts":["Narrative consistency","Budget reconciliation","Requirement coverage","Authorized submission"],"correct":2,"exp":"Requirement coverage uses the actual opportunity instructions as the checklist source.","module":6,"topic":"M6:Proposal Checklist"},{"q":"Proposal Checklist: What should detect different beneficiary numbers in separate sections?","opts":["Requirement coverage","Narrative consistency","Budget reconciliation","Authorized submission"],"correct":1,"exp":"Narrative consistency checks facts, scope and terminology across the application.","module":6,"topic":"M6:Proposal Checklist"},{"q":"Proposal Checklist: What should confirm that totals and funding requests match across files?","opts":["Requirement coverage","Narrative consistency","Authorized submission","Budget reconciliation"],"correct":3,"exp":"Budget reconciliation verifies arithmetic and consistent figures before submission.","module":6,"topic":"M6:Proposal Checklist"},{"q":"Proposal Checklist: What should be confirmed before the application is sent?","opts":["Requirement coverage","Narrative consistency","Budget reconciliation","Authorized submission"],"correct":3,"exp":"Authorized submission checks the permitted signatory, approved version, portal requirements and deadline conditions.","module":6,"topic":"M6:Proposal Checklist"}]},
  {"key":"M7:Project Scope","rows":[{"q":"Project Scope: What should a project scope state positively?","opts":["Excluded work","Deliverable boundary","Included work","Change procedure"],"correct":2,"exp":"Included work identifies the activities and results the project is responsible for delivering.","module":7,"topic":"M7:Project Scope"},{"q":"Project Scope: What prevents stakeholders from assuming that every related need is covered?","opts":["Included work","Deliverable boundary","Change procedure","Excluded work"],"correct":3,"exp":"Excluded work makes relevant boundaries explicit.","module":7,"topic":"M7:Project Scope"},{"q":"Project Scope: What defines when a promised product or service is complete?","opts":["Included work","Deliverable boundary","Excluded work","Change procedure"],"correct":1,"exp":"A deliverable boundary states the agreed content, standard and acceptance evidence.","module":7,"topic":"M7:Project Scope"},{"q":"Project Scope: What should govern a proposed addition to the funded project?","opts":["Included work","Excluded work","Deliverable boundary","Change procedure"],"correct":3,"exp":"A change procedure checks authority, funder approval where required, resources and effects before altering scope.","module":7,"topic":"M7:Project Scope"}]},
  {"key":"M7:Work Plan","rows":[{"q":"Work Plan: What organizes the order in which project work should occur?","opts":["Task owner","Required inputs","Activity sequence","Progress checkpoint"],"correct":2,"exp":"An activity sequence considers dependencies and feasible timing.","module":7,"topic":"M7:Work Plan"},{"q":"Work Plan: What identifies who coordinates a particular task?","opts":["Activity sequence","Task owner","Required inputs","Progress checkpoint"],"correct":1,"exp":"A task owner clarifies responsibility while recognizing supporting roles.","module":7,"topic":"M7:Work Plan"},{"q":"Work Plan: What should be confirmed before starting work that depends on equipment or data?","opts":["Required inputs","Activity sequence","Task owner","Progress checkpoint"],"correct":0,"exp":"Required inputs include resources and prerequisites necessary for execution.","module":7,"topic":"M7:Work Plan"},{"q":"Work Plan: What helps detect delay or a delivery barrier before the project ends?","opts":["Activity sequence","Task owner","Required inputs","Progress checkpoint"],"correct":3,"exp":"A progress checkpoint reviews the relevant deliverable, evidence and needed action.","module":7,"topic":"M7:Work Plan"}]},
  {"key":"M7:Logical Framework (Logframe)","rows":[{"q":"Logical Framework (Logframe): What links activities and outputs with outcomes and a wider goal?","opts":["Indicator","Results hierarchy","Verification source","Assumption"],"correct":1,"exp":"A results hierarchy states the intended logic while recognizing that wider change depends on additional factors.","module":7,"topic":"M7:Logical Framework (Logframe)"},{"q":"Logical Framework (Logframe): What defines the observable evidence of a specified result?","opts":["Results hierarchy","Verification source","Indicator","Assumption"],"correct":2,"exp":"An indicator states what will be measured and how it relates to the result.","module":7,"topic":"M7:Logical Framework (Logframe)"},{"q":"Logical Framework (Logframe): What identifies where the indicator's information will come from?","opts":["Verification source","Results hierarchy","Indicator","Assumption"],"correct":0,"exp":"A verification source must be feasible, suitable and reliable for the measure.","module":7,"topic":"M7:Logical Framework (Logframe)"},{"q":"Logical Framework (Logframe): What records an important condition outside direct project control?","opts":["Results hierarchy","Indicator","Assumption","Verification source"],"correct":2,"exp":"An assumption makes a dependency visible so it can be monitored rather than treated as certain.","module":7,"topic":"M7:Logical Framework (Logframe)"}]},
  {"key":"M7:Results Framework","rows":[{"q":"Results Framework: What connects immediate results with the changes they are expected to support?","opts":["Outcome chain","Baseline","Target","Learning use"],"correct":0,"exp":"An outcome chain makes the intervention's reasoning visible rather than treating every activity as impact.","module":7,"topic":"M7:Results Framework"},{"q":"Results Framework: What records the relevant starting condition?","opts":["Baseline","Outcome chain","Target","Learning use"],"correct":0,"exp":"A baseline provides a comparison point using suitable definitions and data.","module":7,"topic":"M7:Results Framework"},{"q":"Results Framework: What states the intended level of change by a defined time?","opts":["Outcome chain","Target","Baseline","Learning use"],"correct":1,"exp":"A target should be realistic, justified and connected with the indicator.","module":7,"topic":"M7:Results Framework"},{"q":"Results Framework: What should the project do with evidence that results differ from expectations?","opts":["Outcome chain","Baseline","Target","Learning use"],"correct":3,"exp":"Learning use examines causes and adapts decisions responsibly instead of concealing unfavorable findings.","module":7,"topic":"M7:Results Framework"}]},
  {"key":"M7:Risk Assessment","rows":[{"q":"Risk Assessment: What should describe an uncertain event and its possible consequence?","opts":["Likelihood and effect","Risk statement","Mitigation","Monitoring trigger"],"correct":1,"exp":"A risk statement identifies the event, relevant cause and effect on objectives.","module":7,"topic":"M7:Risk Assessment"},{"q":"Risk Assessment: What helps prioritize risks for attention?","opts":["Risk statement","Mitigation","Monitoring trigger","Likelihood and effect"],"correct":3,"exp":"Likelihood and effect are assessed using appropriate evidence and acknowledged uncertainty.","module":7,"topic":"M7:Risk Assessment"},{"q":"Risk Assessment: What reduces an identified exposure where feasible?","opts":["Risk statement","Mitigation","Likelihood and effect","Monitoring trigger"],"correct":1,"exp":"Mitigation defines an action, owner and resources without pretending every risk can be eliminated.","module":7,"topic":"M7:Risk Assessment"},{"q":"Risk Assessment: What signals that a response or review may be needed?","opts":["Risk statement","Monitoring trigger","Likelihood and effect","Mitigation"],"correct":1,"exp":"A monitoring trigger links observable information with a specified decision or action.","module":7,"topic":"M7:Risk Assessment"}]},
  {"key":"M7:Monitoring Indicators","rows":[{"q":"Monitoring Indicators: What prevents different staff from counting the same indicator differently?","opts":["Collection frequency","Data responsibility","Defined measure","Interpretation context"],"correct":2,"exp":"A defined measure specifies unit, numerator or count, scope and relevant exclusions.","module":7,"topic":"M7:Monitoring Indicators"},{"q":"Monitoring Indicators: What should align data gathering with decision needs?","opts":["Collection frequency","Defined measure","Data responsibility","Interpretation context"],"correct":0,"exp":"Collection frequency reflects how often the information is useful and feasible to obtain.","module":7,"topic":"M7:Monitoring Indicators"},{"q":"Monitoring Indicators: What establishes who collects and checks the information?","opts":["Defined measure","Data responsibility","Collection frequency","Interpretation context"],"correct":1,"exp":"Data responsibility assigns suitable roles and quality checks.","module":7,"topic":"M7:Monitoring Indicators"},{"q":"Monitoring Indicators: What should accompany an indicator that changes sharply?","opts":["Defined measure","Collection frequency","Interpretation context","Data responsibility"],"correct":2,"exp":"Interpretation context examines definitions, timing, coverage and possible causes before drawing conclusions.","module":7,"topic":"M7:Monitoring Indicators"}]},
  {"key":"M7:Evaluation Plan","rows":[{"q":"Evaluation Plan: What should determine what an evaluation examines?","opts":["Suitable design","Ethical collection","Evaluation question","Use of findings"],"correct":2,"exp":"An evaluation question identifies the judgment needed about relevance, results or another appropriate aspect.","module":7,"topic":"M7:Evaluation Plan"},{"q":"Evaluation Plan: What should be selected to answer the question credibly?","opts":["Evaluation question","Ethical collection","Suitable design","Use of findings"],"correct":2,"exp":"A suitable design matches methods with the question, available evidence and constraints.","module":7,"topic":"M7:Evaluation Plan"},{"q":"Evaluation Plan: What protects participants when collecting evaluation information?","opts":["Evaluation question","Suitable design","Use of findings","Ethical collection"],"correct":3,"exp":"Ethical collection uses appropriate consent, privacy and safeguarding arrangements.","module":7,"topic":"M7:Evaluation Plan"},{"q":"Evaluation Plan: What should be planned before commissioning the evaluation?","opts":["Evaluation question","Suitable design","Use of findings","Ethical collection"],"correct":2,"exp":"Use of findings identifies who needs the evidence and how it will inform decisions and learning.","module":7,"topic":"M7:Evaluation Plan"}]},
  {"key":"M7:Project Timeline (Gantt Chart)","rows":[{"q":"Project Timeline (Gantt Chart): What should a Gantt chart estimate for each activity?","opts":["Dependency","Milestone","Schedule update","Task duration"],"correct":3,"exp":"Task duration represents the time required under stated assumptions and available capacity.","module":7,"topic":"M7:Project Timeline (Gantt Chart)"},{"q":"Project Timeline (Gantt Chart): What explains why one task cannot start until another is finished?","opts":["Task duration","Dependency","Milestone","Schedule update"],"correct":1,"exp":"A dependency connects activities in the required sequence.","module":7,"topic":"M7:Project Timeline (Gantt Chart)"},{"q":"Project Timeline (Gantt Chart): What identifies a significant approval or completion point?","opts":["Task duration","Dependency","Schedule update","Milestone"],"correct":3,"exp":"A milestone marks a specific checkable event rather than a block of ongoing work.","module":7,"topic":"M7:Project Timeline (Gantt Chart)"},{"q":"Project Timeline (Gantt Chart): What should follow a verified change to an important task's timing?","opts":["Schedule update","Task duration","Dependency","Milestone"],"correct":0,"exp":"A schedule update considers downstream effects and communicates any revised commitments or required approvals.","module":7,"topic":"M7:Project Timeline (Gantt Chart)"}]},
  {"key":"M8:Budget Basics","rows":[{"q":"Budget Basics: What states how many items, days or participants a budget line covers?","opts":["Unit cost","Line total","Quantity","Budget total"],"correct":2,"exp":"Quantity must use a clear unit and match the project design.","module":8,"topic":"M8:Budget Basics"},{"q":"Budget Basics: What states the price per defined item or unit?","opts":["Quantity","Line total","Unit cost","Budget total"],"correct":2,"exp":"A unit cost should have a reasonable, documented basis rather than an invented amount.","module":8,"topic":"M8:Budget Basics"},{"q":"Budget Basics: What is quantity multiplied by the cost per unit?","opts":["Quantity","Line total","Unit cost","Budget total"],"correct":1,"exp":"The line total must use consistent units and correct arithmetic.","module":8,"topic":"M8:Budget Basics"},{"q":"Budget Basics: What should reconcile with the request and approved contributions?","opts":["Quantity","Unit cost","Budget total","Line total"],"correct":2,"exp":"The budget total combines relevant lines and must follow the funder's format and cost rules.","module":8,"topic":"M8:Budget Basics"}]},
  {"key":"M8:Personnel Costs","rows":[{"q":"Personnel Costs: What should connect a staffing budget with the work plan?","opts":["Pay basis","Role and effort","Time allocation","Permitted employment costs"],"correct":1,"exp":"Role and effort explain the work required and the amount of staff time proposed.","module":8,"topic":"M8:Personnel Costs"},{"q":"Personnel Costs: What should support a proposed personnel rate?","opts":["Role and effort","Time allocation","Pay basis","Permitted employment costs"],"correct":2,"exp":"The pay basis uses relevant authorized information and consistent units.","module":8,"topic":"M8:Personnel Costs"},{"q":"Personnel Costs: What prevents charging the same full-time effort to multiple grants?","opts":["Role and effort","Pay basis","Permitted employment costs","Time allocation"],"correct":3,"exp":"Time allocation records the actual basis for distributing work and must meet applicable award requirements.","module":8,"topic":"M8:Personnel Costs"},{"q":"Personnel Costs: What should be checked before adding employment-related charges?","opts":["Role and effort","Pay basis","Permitted employment costs","Time allocation"],"correct":2,"exp":"Permitted costs depend on funder terms, applicable obligations and the organization's legitimate arrangements.","module":8,"topic":"M8:Personnel Costs"}]},
  {"key":"M8:Equipment Costs","rows":[{"q":"Equipment Costs: What should justify including equipment in a project budget?","opts":["Specification","Cost evidence","Ownership conditions","Project need"],"correct":3,"exp":"A project need connects the asset with an actual activity and intended use.","module":8,"topic":"M8:Equipment Costs"},{"q":"Equipment Costs: What enables comparable quotations for the proposed equipment?","opts":["Specification","Project need","Cost evidence","Ownership conditions"],"correct":0,"exp":"A specification defines suitable requirements without unnecessarily favoring a supplier.","module":8,"topic":"M8:Equipment Costs"},{"q":"Equipment Costs: What should support the estimated purchase amount?","opts":["Project need","Cost evidence","Specification","Ownership conditions"],"correct":1,"exp":"Cost evidence uses relevant quotations or another acceptable documented basis.","module":8,"topic":"M8:Equipment Costs"},{"q":"Equipment Costs: What should be checked about an asset purchased under an award?","opts":["Ownership conditions","Project need","Specification","Cost evidence"],"correct":0,"exp":"Ownership, use, recordkeeping and disposal conditions depend on the actual agreement and applicable rules.","module":8,"topic":"M8:Equipment Costs"}]},
  {"key":"M8:Operational Costs","rows":[{"q":"Operational Costs: What should connect a travel or venue expense with the proposal?","opts":["Activity connection","Calculation basis","Cost eligibility","Allocation method"],"correct":0,"exp":"An activity connection explains why the expense is necessary for the work.","module":8,"topic":"M8:Operational Costs"},{"q":"Operational Costs: What should make the amount reproducible for a reviewer?","opts":["Activity connection","Cost eligibility","Allocation method","Calculation basis"],"correct":3,"exp":"A calculation basis states quantity, period and unit cost with suitable evidence.","module":8,"topic":"M8:Operational Costs"},{"q":"Operational Costs: What determines whether the award may cover the expense?","opts":["Activity connection","Cost eligibility","Calculation basis","Allocation method"],"correct":1,"exp":"Cost eligibility follows the specific funder and award requirements rather than assuming all operating expenses qualify.","module":8,"topic":"M8:Operational Costs"},{"q":"Operational Costs: What should explain a shared expense charged partly to the project?","opts":["Activity connection","Calculation basis","Allocation method","Cost eligibility"],"correct":2,"exp":"An allocation method provides a justified, consistent basis that fits the applicable terms and avoids duplicate charging.","module":8,"topic":"M8:Operational Costs"}]},
  {"key":"M8:Indirect Costs","rows":[{"q":"Indirect Costs: What commonly distinguishes an indirect cost from a project-specific expense?","opts":["Permitted rate or method","Applicable base","Shared support cost","Double-counting check"],"correct":2,"exp":"A shared support cost benefits wider operations and is not assigned exclusively to one project without an appropriate basis.","module":8,"topic":"M8:Indirect Costs"},{"q":"Indirect Costs: What should be verified before including overhead in a grant budget?","opts":["Shared support cost","Applicable base","Double-counting check","Permitted rate or method"],"correct":3,"exp":"The permitted rate or method depends on the actual funder rules and relevant authorization.","module":8,"topic":"M8:Indirect Costs"},{"q":"Indirect Costs: What determines which costs are included when calculating a percentage overhead amount?","opts":["Applicable base","Shared support cost","Permitted rate or method","Double-counting check"],"correct":0,"exp":"The applicable base must follow the specified method; a percentage cannot be applied blindly to every expense.","module":8,"topic":"M8:Indirect Costs"},{"q":"Indirect Costs: What should ensure an administrative expense is not charged both directly and through overhead?","opts":["Shared support cost","Permitted rate or method","Applicable base","Double-counting check"],"correct":3,"exp":"A double-counting check reconciles cost treatment and allocation with the award's requirements.","module":8,"topic":"M8:Indirect Costs"}]},
  {"key":"M8:Budget Justification","rows":[{"q":"Budget Justification: What should explain why a budget line is necessary?","opts":["Calculation explanation","Reasonableness evidence","Cost purpose","Narrative alignment"],"correct":2,"exp":"A cost purpose connects the expense with an activity and required result.","module":8,"topic":"M8:Budget Justification"},{"q":"Budget Justification: What should let a reviewer reproduce a budgeted amount?","opts":["Cost purpose","Calculation explanation","Reasonableness evidence","Narrative alignment"],"correct":1,"exp":"A calculation explanation states quantity, unit, rate and period clearly.","module":8,"topic":"M8:Budget Justification"},{"q":"Budget Justification: What should support the claim that an estimated cost is reasonable?","opts":["Cost purpose","Reasonableness evidence","Calculation explanation","Narrative alignment"],"correct":1,"exp":"Relevant quotations or another suitable basis provide evidence, subject to funder requirements.","module":8,"topic":"M8:Budget Justification"},{"q":"Budget Justification: What prevents the justification from describing work absent from the proposal?","opts":["Cost purpose","Calculation explanation","Narrative alignment","Reasonableness evidence"],"correct":2,"exp":"Narrative alignment reconciles activities, staffing, timing and budget assumptions across the application.","module":8,"topic":"M8:Budget Justification"}]},
  {"key":"M8:Cost Sharing","rows":[{"q":"Cost Sharing: What should be checked before assuming a grant requires matching support?","opts":["Required contribution","Eligible source","Valuation basis","Documented commitment"],"correct":0,"exp":"A required contribution exists only under the actual opportunity or award conditions.","module":8,"topic":"M8:Cost Sharing"},{"q":"Cost Sharing: What should establish whether a proposed contribution may count?","opts":["Required contribution","Valuation basis","Documented commitment","Eligible source"],"correct":3,"exp":"An eligible source must satisfy the funder's rules and cannot be assumed valid because support is available.","module":8,"topic":"M8:Cost Sharing"},{"q":"Cost Sharing: What should support the recorded value of an in-kind contribution?","opts":["Valuation basis","Required contribution","Eligible source","Documented commitment"],"correct":0,"exp":"A valuation basis follows the applicable method and evidence rather than inventing a cash equivalent.","module":8,"topic":"M8:Cost Sharing"},{"q":"Cost Sharing: What should support a partner contribution that the budget depends on?","opts":["Required contribution","Documented commitment","Eligible source","Valuation basis"],"correct":1,"exp":"A documented commitment confirms authorization, amount or basis, timing and any required conditions.","module":8,"topic":"M8:Cost Sharing"}]},
  {"key":"M8:Financial Sustainability","rows":[{"q":"Financial Sustainability: What should be identified before promising continuation after the grant ends?","opts":["Continuing cost","Reliable support","Cash timing","Scenario check"],"correct":0,"exp":"Continuing costs show the resources needed to maintain the intended value.","module":8,"topic":"M8:Financial Sustainability"},{"q":"Financial Sustainability: What should support a claim that future operations can be funded?","opts":["Continuing cost","Cash timing","Scenario check","Reliable support"],"correct":3,"exp":"Reliable support uses confirmed or responsibly qualified funding assumptions rather than guaranteed future awards.","module":8,"topic":"M8:Financial Sustainability"},{"q":"Financial Sustainability: What should be reviewed even when total promised support appears sufficient?","opts":["Cash timing","Continuing cost","Reliable support","Scenario check"],"correct":0,"exp":"Cash timing checks whether funds will be available when obligations must be paid.","module":8,"topic":"M8:Financial Sustainability"},{"q":"Financial Sustainability: What tests whether the continuation plan remains feasible under less favorable assumptions?","opts":["Continuing cost","Scenario check","Reliable support","Cash timing"],"correct":1,"exp":"A scenario check examines alternative income, cost or timing conditions and suitable responses.","module":8,"topic":"M8:Financial Sustainability"}]},
  {"key":"M8:Budget Review","rows":[{"q":"Budget Review: What should detect a spreadsheet line total that does not match quantity and unit cost?","opts":["Rules check","Work-plan comparison","Arithmetic check","Funding reconciliation"],"correct":2,"exp":"An arithmetic check verifies formulas, units and totals rather than trusting formatting.","module":8,"topic":"M8:Budget Review"},{"q":"Budget Review: What should confirm that proposed costs are allowed?","opts":["Arithmetic check","Work-plan comparison","Funding reconciliation","Rules check"],"correct":3,"exp":"A rules check uses the actual opportunity and award conditions.","module":8,"topic":"M8:Budget Review"},{"q":"Budget Review: What should reveal that a budget omits a planned activity?","opts":["Arithmetic check","Work-plan comparison","Rules check","Funding reconciliation"],"correct":1,"exp":"Work-plan comparison checks whether necessary resources match the narrative and timeline.","module":8,"topic":"M8:Budget Review"},{"q":"Budget Review: What should confirm that requested funding and eligible contributions sum to the stated total?","opts":["Arithmetic check","Funding reconciliation","Rules check","Work-plan comparison"],"correct":1,"exp":"Funding reconciliation verifies amounts, sources and commitments across budget documents.","module":8,"topic":"M8:Budget Review"}]},
  {"key":"M9:Editing Techniques","rows":[{"q":"Editing Techniques: What should an editor examine before polishing individual sentences?","opts":["Argument clarity","Structure review","Consistency editing","Reader-focused revision"],"correct":1,"exp":"Structure review checks whether the proposal's sections answer the required questions in a coherent order.","module":9,"topic":"M9:Editing Techniques"},{"q":"Editing Techniques: What should make a recommendation understandable and supported?","opts":["Structure review","Argument clarity","Consistency editing","Reader-focused revision"],"correct":1,"exp":"Argument clarity connects the claim, evidence and reasoning while removing unsupported assertions.","module":9,"topic":"M9:Editing Techniques"},{"q":"Editing Techniques: What should detect different dates or beneficiary figures in the same application?","opts":["Structure review","Consistency editing","Argument clarity","Reader-focused revision"],"correct":1,"exp":"Consistency editing reconciles facts, terminology and assumptions across sections.","module":9,"topic":"M9:Editing Techniques"},{"q":"Editing Techniques: What should guide removing unnecessary jargon?","opts":["Structure review","Argument clarity","Consistency editing","Reader-focused revision"],"correct":3,"exp":"Reader-focused revision uses clear language suitable for the evaluator without changing the underlying facts.","module":9,"topic":"M9:Editing Techniques"}]},
  {"key":"M9:Proofreading","rows":[{"q":"Proofreading: What should be examined after substantive editing is complete?","opts":["Numbers and names","Spelling and grammar","Cross-references","Final-copy check"],"correct":1,"exp":"Spelling and grammar checks improve correctness but do not establish factual or funding compliance.","module":9,"topic":"M9:Proofreading"},{"q":"Proofreading: What should be verified even when automated spelling checks find no issue?","opts":["Spelling and grammar","Cross-references","Final-copy check","Numbers and names"],"correct":3,"exp":"Numbers and names require comparison with authoritative records and calculations.","module":9,"topic":"M9:Proofreading"},{"q":"Proofreading: What should ensure that a reference to an attachment points to the right file?","opts":["Spelling and grammar","Cross-references","Numbers and names","Final-copy check"],"correct":1,"exp":"Cross-reference checking connects labels, sections and documents accurately.","module":9,"topic":"M9:Proofreading"},{"q":"Proofreading: What should be done after converting or uploading the application?","opts":["Spelling and grammar","Numbers and names","Final-copy check","Cross-references"],"correct":2,"exp":"A final-copy check confirms that the actual submitted format retains approved content and readability.","module":9,"topic":"M9:Proofreading"}]},
  {"key":"M9:Compliance Checks","rows":[{"q":"Compliance Checks: What should a compliance checklist be built from?","opts":["Content limits","Mandatory conditions","Required declarations","Submission evidence"],"correct":1,"exp":"Mandatory conditions come from the specific current funding instructions and applicable requirements.","module":9,"topic":"M9:Compliance Checks"},{"q":"Compliance Checks: What should detect an application section exceeding a stated word or page limit?","opts":["Mandatory conditions","Required declarations","Content limits","Submission evidence"],"correct":2,"exp":"Content-limit checks apply the actual counting rules and format conditions.","module":9,"topic":"M9:Compliance Checks"},{"q":"Compliance Checks: What should establish that required confirmations are completed by an authorized person?","opts":["Required declarations","Mandatory conditions","Content limits","Submission evidence"],"correct":0,"exp":"Required declarations must be accurate, complete and appropriately approved.","module":9,"topic":"M9:Compliance Checks"},{"q":"Compliance Checks: What should an applicant retain after successful delivery to the portal?","opts":["Mandatory conditions","Content limits","Required declarations","Submission evidence"],"correct":3,"exp":"Submission evidence records the relevant acknowledgment and status, without treating receipt as an award decision.","module":9,"topic":"M9:Compliance Checks"}]},
  {"key":"M9:Proposal Formatting","rows":[{"q":"Proposal Formatting: What should govern required font, form and page arrangements?","opts":["Readable hierarchy","Accessible presentation","Funder-specified format","Export verification"],"correct":2,"exp":"Use the funder's specified format rather than substituting a preferred design.","module":9,"topic":"M9:Proposal Formatting"},{"q":"Proposal Formatting: What helps a reviewer locate the proposal's sections quickly?","opts":["Funder-specified format","Accessible presentation","Readable hierarchy","Export verification"],"correct":2,"exp":"A readable hierarchy uses clear headings and consistent organization within permitted formatting.","module":9,"topic":"M9:Proposal Formatting"},{"q":"Proposal Formatting: What supports readers who cannot rely on color alone?","opts":["Funder-specified format","Accessible presentation","Readable hierarchy","Export verification"],"correct":1,"exp":"Accessible presentation uses readable contrast, labels and text explanations for important visuals.","module":9,"topic":"M9:Proposal Formatting"},{"q":"Proposal Formatting: What should be checked after creating the final PDF or other required file?","opts":["Funder-specified format","Readable hierarchy","Accessible presentation","Export verification"],"correct":3,"exp":"Export verification examines missing text, broken tables and file suitability before submission.","module":9,"topic":"M9:Proposal Formatting"}]},
  {"key":"M9:Attachments","rows":[{"q":"Attachments: What should determine which supporting files are included?","opts":["Correct version","Authorized content","Required list","File reconciliation"],"correct":2,"exp":"The required list comes from the actual instructions, not an unrelated application's attachments.","module":9,"topic":"M9:Attachments"},{"q":"Attachments: What prevents submission of an outdated budget or registration document?","opts":["Required list","Authorized content","File reconciliation","Correct version"],"correct":3,"exp":"Correct-version checks identify the approved current copy and relevant validity period.","module":9,"topic":"M9:Attachments"},{"q":"Attachments: What should precede including a partner letter or private record?","opts":["Required list","Correct version","Authorized content","File reconciliation"],"correct":2,"exp":"Authorized content requires appropriate approval and necessary privacy safeguards.","module":9,"topic":"M9:Attachments"},{"q":"Attachments: What should confirm that filenames and references match the uploaded documents?","opts":["File reconciliation","Required list","Correct version","Authorized content"],"correct":0,"exp":"File reconciliation checks labels, order, completeness and the content actually attached.","module":9,"topic":"M9:Attachments"}]},
  {"key":"M9:Submission Portals","rows":[{"q":"Submission Portals: What should be confirmed before a staff member submits for an organization?","opts":["File requirements","Validation status","Account permission","Receipt record"],"correct":2,"exp":"Account permission verifies the relevant preparation and submission authority.","module":9,"topic":"M9:Submission Portals"},{"q":"Submission Portals: What should be checked before uploading a document?","opts":["Account permission","Validation status","Receipt record","File requirements"],"correct":3,"exp":"File requirements can include type, size, naming and required content and must be verified for the portal.","module":9,"topic":"M9:Submission Portals"},{"q":"Submission Portals: What may indicate that an uploaded application still needs correction?","opts":["Validation status","Account permission","File requirements","Receipt record"],"correct":0,"exp":"Validation status may show missing fields or errors; upload alone does not prove compliant submission.","module":9,"topic":"M9:Submission Portals"},{"q":"Submission Portals: What should the team keep after completing the required submission process?","opts":["Account permission","File requirements","Receipt record","Validation status"],"correct":2,"exp":"A receipt record and relevant status evidence support follow-up and troubleshooting.","module":9,"topic":"M9:Submission Portals"}]},
  {"key":"M9:Submission Deadlines","rows":[{"q":"Submission Deadlines: What should be verified before interpreting a published cutoff time?","opts":["Internal review date","Registration lead time","Official time zone","Contingency margin"],"correct":2,"exp":"The official time zone and deadline conditions determine the applicable submission window.","module":9,"topic":"M9:Submission Deadlines"},{"q":"Submission Deadlines: What helps complete approvals before the external deadline?","opts":["Official time zone","Registration lead time","Internal review date","Contingency margin"],"correct":2,"exp":"An internal review date leaves time to resolve issues and obtain authorized sign-off.","module":9,"topic":"M9:Submission Deadlines"},{"q":"Submission Deadlines: What should be considered if an application requires account setup or organizational registration?","opts":["Registration lead time","Official time zone","Internal review date","Contingency margin"],"correct":0,"exp":"Registration lead time may differ from the final application deadline and should be planned early.","module":9,"topic":"M9:Submission Deadlines"},{"q":"Submission Deadlines: What reduces avoidable risk from last-minute upload errors?","opts":["Contingency margin","Official time zone","Internal review date","Registration lead time"],"correct":0,"exp":"A contingency margin allows time for validation and technical assistance without assuming extensions will be granted.","module":9,"topic":"M9:Submission Deadlines"}]},
  {"key":"M9:Follow-Up Strategies","rows":[{"q":"Follow-Up Strategies: What should govern how an applicant approaches a funder after submission?","opts":["Application status","Permitted contact","Constructive clarification","Learning from feedback"],"correct":1,"exp":"Permitted contact follows the donor's stated process rather than repeated unsolicited pressure.","module":9,"topic":"M9:Follow-Up Strategies"},{"q":"Follow-Up Strategies: What should be checked before asking whether an application was received?","opts":["Permitted contact","Constructive clarification","Application status","Learning from feedback"],"correct":2,"exp":"Application status and retained acknowledgments may already answer the question.","module":9,"topic":"M9:Follow-Up Strategies"},{"q":"Follow-Up Strategies: What should a response to a funder query provide?","opts":["Constructive clarification","Permitted contact","Application status","Learning from feedback"],"correct":0,"exp":"Constructive clarification supplies accurate requested information through the approved route.","module":9,"topic":"M9:Follow-Up Strategies"},{"q":"Follow-Up Strategies: What can strengthen a later application after rejection?","opts":["Permitted contact","Application status","Learning from feedback","Constructive clarification"],"correct":2,"exp":"Feedback can reveal fit or quality issues, but a revision should still follow the next opportunity's current conditions.","module":9,"topic":"M9:Follow-Up Strategies"}]},
  {"key":"M10:Principles of Fundraising","rows":[{"q":"Principles of Fundraising: What should connect an appeal with the organization it represents?","opts":["Mission-led appeal","Voluntary informed giving","Relationship building","Responsible stewardship"],"correct":0,"exp":"A mission-led appeal seeks support for a credible purpose and intended benefit.","module":10,"topic":"M10:Principles of Fundraising"},{"q":"Principles of Fundraising: What should a donor understand before deciding to contribute?","opts":["Voluntary informed giving","Mission-led appeal","Relationship building","Responsible stewardship"],"correct":0,"exp":"Voluntary informed giving requires accurate information without manipulative pressure or unsupported guarantees.","module":10,"topic":"M10:Principles of Fundraising"},{"q":"Principles of Fundraising: What supports fundraising beyond one isolated transaction?","opts":["Mission-led appeal","Relationship building","Voluntary informed giving","Responsible stewardship"],"correct":1,"exp":"Relationship building involves listening, trust and relevant engagement.","module":10,"topic":"M10:Principles of Fundraising"},{"q":"Principles of Fundraising: What must continue after a contribution is accepted?","opts":["Mission-led appeal","Voluntary informed giving","Responsible stewardship","Relationship building"],"correct":2,"exp":"Responsible stewardship follows accepted donor conditions, records use and reports honestly.","module":10,"topic":"M10:Principles of Fundraising"}]},
  {"key":"M10:Fundraising Ethics","rows":[{"q":"Fundraising Ethics: What should a fundraiser do with an impact claim that lacks supporting evidence?","opts":["Accurate appeal","Respect for donor choice","Protection of information","Appropriate compensation"],"correct":0,"exp":"Use accurate information and disclose relevant limits instead of exaggerating results.","module":10,"topic":"M10:Fundraising Ethics"},{"q":"Fundraising Ethics: What should guide responding to a donor who declines an appeal?","opts":["Respect for donor choice","Accurate appeal","Protection of information","Appropriate compensation"],"correct":0,"exp":"Respect donor choice and preferences rather than applying coercive pressure.","module":10,"topic":"M10:Fundraising Ethics"},{"q":"Fundraising Ethics: What should prevent unauthorized sharing of a donor list?","opts":["Accurate appeal","Respect for donor choice","Protection of information","Appropriate compensation"],"correct":2,"exp":"Protect information according to appropriate permission, organizational policy and applicable requirements.","module":10,"topic":"M10:Fundraising Ethics"},{"q":"Fundraising Ethics: Under AFP ethical standards, what should guide pricing fundraising work instead of taking a percentage of donations?","opts":["Accurate appeal","Respect for donor choice","Protection of information","Appropriate compensation"],"correct":3,"exp":"AFP standards reject percentage-based fundraising compensation; use an appropriate nonpercentage arrangement and check other applicable obligations.","module":10,"topic":"M10:Fundraising Ethics"}]},
  {"key":"M10:Individual Giving","rows":[{"q":"Individual Giving: What should an individual appeal connect with?","opts":["Donation choice","Relevant appeal","Gift record","Acknowledgment"],"correct":1,"exp":"A relevant appeal explains the cause, credible use of support and the donor's possible contribution.","module":10,"topic":"M10:Individual Giving"},{"q":"Individual Giving: What should remain clear when a person is asked to give?","opts":["Relevant appeal","Gift record","Acknowledgment","Donation choice"],"correct":3,"exp":"Donation choice includes voluntary participation and accurate information about any accepted restrictions.","module":10,"topic":"M10:Individual Giving"},{"q":"Individual Giving: What should an organization record when a contribution is received?","opts":["Relevant appeal","Donation choice","Gift record","Acknowledgment"],"correct":2,"exp":"A gift record captures appropriate amount, source, conditions and transaction details while protecting personal information.","module":10,"topic":"M10:Individual Giving"},{"q":"Individual Giving: What should follow receipt of an individual's gift?","opts":["Relevant appeal","Donation choice","Acknowledgment","Gift record"],"correct":2,"exp":"Acknowledgment thanks the donor and provides accurate information under the relevant process without inventing tax treatment.","module":10,"topic":"M10:Individual Giving"}]},
  {"key":"M10:Corporate Sponsorship","rows":[{"q":"Corporate Sponsorship: What distinguishes sponsorship planning from simply requesting a charitable gift?","opts":["Defined benefits","Written agreement","Delivery evidence","Mutual value"],"correct":3,"exp":"Mutual value considers the sponsor's agreed benefits and the organization's mission and responsibilities.","module":10,"topic":"M10:Corporate Sponsorship"},{"q":"Corporate Sponsorship: What should be explicit before promising a sponsor publicity?","opts":["Mutual value","Written agreement","Defined benefits","Delivery evidence"],"correct":2,"exp":"Defined benefits state what the organization can legitimately deliver and any limits.","module":10,"topic":"M10:Corporate Sponsorship"},{"q":"Corporate Sponsorship: What should record the sponsorship obligations and permissions?","opts":["Written agreement","Mutual value","Defined benefits","Delivery evidence"],"correct":0,"exp":"A written agreement clarifies deliverables, payment, timing, branding and relevant conditions.","module":10,"topic":"M10:Corporate Sponsorship"},{"q":"Corporate Sponsorship: What should show that promised sponsorship benefits were supplied?","opts":["Mutual value","Delivery evidence","Defined benefits","Written agreement"],"correct":1,"exp":"Delivery evidence records actual performance rather than assuming that payment proves all obligations were met.","module":10,"topic":"M10:Corporate Sponsorship"}]},
  {"key":"M10:Major Donors","rows":[{"q":"Major Donors: What should be assessed before approaching a potential major donor?","opts":["Listening and cultivation","Tailored request","Stewardship plan","Suitability research"],"correct":3,"exp":"Suitability research considers legitimate interests, relationship context and responsible use of information.","module":10,"topic":"M10:Major Donors"},{"q":"Major Donors: What helps understand the donor's priorities before making an ask?","opts":["Suitability research","Tailored request","Stewardship plan","Listening and cultivation"],"correct":3,"exp":"Listening and cultivation develop an informed relationship rather than assuming ability to give equals willingness.","module":10,"topic":"M10:Major Donors"},{"q":"Major Donors: What should shape a major-gift request?","opts":["Suitability research","Tailored request","Listening and cultivation","Stewardship plan"],"correct":1,"exp":"A tailored request connects an authorized, credible project with the donor's relevant interests and voluntary choice.","module":10,"topic":"M10:Major Donors"},{"q":"Major Donors: What should accompany acceptance of a significant gift?","opts":["Suitability research","Listening and cultivation","Stewardship plan","Tailored request"],"correct":2,"exp":"A stewardship plan defines acknowledgment, agreed use, reporting and appropriate ongoing communication.","module":10,"topic":"M10:Major Donors"}]},
  {"key":"M10:Membership Programs","rows":[{"q":"Membership Programs: What should a membership program explain to potential participants?","opts":["Contribution terms","Member engagement","Program review","Membership value"],"correct":3,"exp":"Membership value identifies the relevant benefits or shared purpose honestly.","module":10,"topic":"M10:Membership Programs"},{"q":"Membership Programs: What should be clear before collecting a recurring fee?","opts":["Membership value","Member engagement","Program review","Contribution terms"],"correct":3,"exp":"Contribution terms specify amounts, periods, benefits and applicable renewal or cancellation arrangements.","module":10,"topic":"M10:Membership Programs"},{"q":"Membership Programs: What helps maintain a useful relationship with members?","opts":["Membership value","Contribution terms","Program review","Member engagement"],"correct":3,"exp":"Member engagement provides relevant communication and opportunities to participate.","module":10,"topic":"M10:Membership Programs"},{"q":"Membership Programs: What should test whether the program remains sustainable and worthwhile?","opts":["Program review","Membership value","Contribution terms","Member engagement"],"correct":0,"exp":"Program review considers income, costs, participation and mission-related value rather than enrollment alone.","module":10,"topic":"M10:Membership Programs"}]},
  {"key":"M10:Planned Giving","rows":[{"q":"Planned Giving: What often distinguishes a planned gift from an immediately received donation?","opts":["Qualified specialist advice","Longer-term intention","Documented conditions","Uncertain receipt timing"],"correct":1,"exp":"A longer-term intention may concern future or estate-related support and does not automatically create available cash now.","module":10,"topic":"M10:Planned Giving"},{"q":"Planned Giving: What should a fundraiser recommend for complex legal or tax arrangements?","opts":["Longer-term intention","Documented conditions","Qualified specialist advice","Uncertain receipt timing"],"correct":2,"exp":"Qualified specialist advice is needed for the donor's circumstances and applicable jurisdiction; the fundraiser should not invent personalized advice.","module":10,"topic":"M10:Planned Giving"},{"q":"Planned Giving: What should an organization clarify before recording the proposed gift?","opts":["Longer-term intention","Qualified specialist advice","Uncertain receipt timing","Documented conditions"],"correct":3,"exp":"Documented conditions establish the nature of the commitment and any relevant restrictions or authorization.","module":10,"topic":"M10:Planned Giving"},{"q":"Planned Giving: What should be recognized when budgeting for future planned support?","opts":["Longer-term intention","Qualified specialist advice","Uncertain receipt timing","Documented conditions"],"correct":2,"exp":"Receipt timing and amount may be uncertain, so the intention should not be treated automatically as current unrestricted funds.","module":10,"topic":"M10:Planned Giving"}]},
  {"key":"M10:Annual Giving Campaigns","rows":[{"q":"Annual Giving Campaigns: What should define the purpose and intended result of the campaign?","opts":["Annual objective","Campaign calendar","Audience plan","Results review"],"correct":0,"exp":"An annual objective connects the fundraising target with credible mission-related needs.","module":10,"topic":"M10:Annual Giving Campaigns"},{"q":"Annual Giving Campaigns: What coordinates appeals, events and stewardship through the period?","opts":["Campaign calendar","Annual objective","Audience plan","Results review"],"correct":0,"exp":"A campaign calendar sequences activities with feasible ownership and timing.","module":10,"topic":"M10:Annual Giving Campaigns"},{"q":"Annual Giving Campaigns: What helps make messages relevant to different supporter groups?","opts":["Annual objective","Campaign calendar","Audience plan","Results review"],"correct":2,"exp":"An audience plan uses appropriate segmentation and consent rather than sending every donor every message.","module":10,"topic":"M10:Annual Giving Campaigns"},{"q":"Annual Giving Campaigns: What should evaluate the campaign beyond total donations alone?","opts":["Annual objective","Campaign calendar","Results review","Audience plan"],"correct":2,"exp":"Results review examines costs, donor experience, retention and relevant mission value.","module":10,"topic":"M10:Annual Giving Campaigns"}]},
  {"key":"M11:Fundraising Planning","rows":[{"q":"Fundraising Planning: What should establish why funds are being sought?","opts":["Source mix","Capacity plan","Review measures","Funding need"],"correct":3,"exp":"A funding need connects a justified amount with authorized work and its resources.","module":11,"topic":"M11:Fundraising Planning"},{"q":"Fundraising Planning: What reduces reliance on one uncertain income route?","opts":["Funding need","Capacity plan","Source mix","Review measures"],"correct":2,"exp":"A source mix considers feasible grants, individual support and other suitable fundraising channels.","module":11,"topic":"M11:Fundraising Planning"},{"q":"Fundraising Planning: What should be checked before scheduling several campaigns at once?","opts":["Funding need","Source mix","Capacity plan","Review measures"],"correct":2,"exp":"A capacity plan assesses staff, volunteers, systems and time required to deliver responsibly.","module":11,"topic":"M11:Fundraising Planning"},{"q":"Fundraising Planning: What should support adapting the plan during implementation?","opts":["Funding need","Source mix","Review measures","Capacity plan"],"correct":2,"exp":"Review measures examine relevant income, costs, engagement and delivery evidence.","module":11,"topic":"M11:Fundraising Planning"}]},
  {"key":"M11:Campaign Design","rows":[{"q":"Campaign Design: What should be agreed before creating campaign materials?","opts":["Credible message","Delivery channels","Audience and objective","Test and measurement"],"correct":2,"exp":"Audience and objective clarify whom the campaign addresses and what appropriate action it seeks.","module":11,"topic":"M11:Campaign Design"},{"q":"Campaign Design: What should an appeal state about the cause?","opts":["Credible message","Audience and objective","Delivery channels","Test and measurement"],"correct":0,"exp":"A credible message connects accurate need and intended use with a truthful request.","module":11,"topic":"M11:Campaign Design"},{"q":"Campaign Design: What should guide choosing email, events or social media?","opts":["Audience and objective","Credible message","Delivery channels","Test and measurement"],"correct":2,"exp":"Delivery channels should fit audience access, preferences, resources and applicable permissions.","module":11,"topic":"M11:Campaign Design"},{"q":"Campaign Design: What should precede scaling an unproven appeal approach?","opts":["Audience and objective","Credible message","Test and measurement","Delivery channels"],"correct":2,"exp":"Testing and measurement gather relevant evidence about response, cost and donor experience.","module":11,"topic":"M11:Campaign Design"}]},
  {"key":"M11:Donor Segmentation","rows":[{"q":"Donor Segmentation: What is the purpose of grouping donors by suitable shared characteristics?","opts":["Responsible data use","Relevant grouping","Tailored communication","Segment review"],"correct":1,"exp":"Relevant grouping helps plan communication that fits actual interests or relationships.","module":11,"topic":"M11:Donor Segmentation"},{"q":"Donor Segmentation: What should constrain the data used to create donor groups?","opts":["Relevant grouping","Responsible data use","Tailored communication","Segment review"],"correct":1,"exp":"Responsible data use limits collection and access to appropriate purposes and applicable permissions.","module":11,"topic":"M11:Donor Segmentation"},{"q":"Donor Segmentation: What should change after useful segments are identified?","opts":["Relevant grouping","Responsible data use","Segment review","Tailored communication"],"correct":3,"exp":"Tailored communication adjusts relevant content and contact arrangements without stereotyping individuals.","module":11,"topic":"M11:Donor Segmentation"},{"q":"Donor Segmentation: What should check whether a grouping remains useful?","opts":["Relevant grouping","Responsible data use","Segment review","Tailored communication"],"correct":2,"exp":"Segment review examines actual preferences and responses and updates inaccurate assumptions.","module":11,"topic":"M11:Donor Segmentation"}]},
  {"key":"M11:Donor Stewardship","rows":[{"q":"Donor Stewardship: What should govern expenditure of a restricted contribution?","opts":["Timely acknowledgment","Verified reporting","Ongoing dialogue","Respect agreed use"],"correct":3,"exp":"Respect agreed use and obtain appropriate authorization before changing accepted restrictions.","module":11,"topic":"M11:Donor Stewardship"},{"q":"Donor Stewardship: What should follow receipt of a contribution?","opts":["Respect agreed use","Timely acknowledgment","Verified reporting","Ongoing dialogue"],"correct":1,"exp":"Timely acknowledgment thanks the donor and confirms accurate relevant details.","module":11,"topic":"M11:Donor Stewardship"},{"q":"Donor Stewardship: What should support claims made in a donor update?","opts":["Respect agreed use","Verified reporting","Timely acknowledgment","Ongoing dialogue"],"correct":1,"exp":"Verified reporting distinguishes documented results, estimates and unresolved issues.","module":11,"topic":"M11:Donor Stewardship"},{"q":"Donor Stewardship: What can maintain trust after the initial gift?","opts":["Ongoing dialogue","Respect agreed use","Timely acknowledgment","Verified reporting"],"correct":0,"exp":"Ongoing dialogue listens to preferences and provides suitable information without treating every contact as another ask.","module":11,"topic":"M11:Donor Stewardship"}]},
  {"key":"M11:Relationship Building","rows":[{"q":"Relationship Building: What should a fundraiser learn before assuming which cause a supporter values?","opts":["Reliable commitments","Relevant contact","Understanding interests","Respectful boundaries"],"correct":2,"exp":"Understanding interests comes from appropriate research and listening rather than income or identity stereotypes.","module":11,"topic":"M11:Relationship Building"},{"q":"Relationship Building: What behavior helps establish trust over time?","opts":["Understanding interests","Reliable commitments","Relevant contact","Respectful boundaries"],"correct":1,"exp":"Reliable commitments mean providing agreed information or honestly explaining a necessary change.","module":11,"topic":"M11:Relationship Building"},{"q":"Relationship Building: What should determine the content and frequency of communication?","opts":["Understanding interests","Reliable commitments","Relevant contact","Respectful boundaries"],"correct":2,"exp":"Relevant contact reflects the relationship, donor preferences and appropriate permissions.","module":11,"topic":"M11:Relationship Building"},{"q":"Relationship Building: What should be respected when a donor requests no further appeals?","opts":["Understanding interests","Reliable commitments","Respectful boundaries","Relevant contact"],"correct":2,"exp":"Respectful boundaries honor the request through the relevant process rather than applying pressure.","module":11,"topic":"M11:Relationship Building"}]},
  {"key":"M11:Volunteer Fundraising","rows":[{"q":"Volunteer Fundraising: What should a volunteer understand before representing the organization?","opts":["Training and safeguards","Role brief","Authorized materials","Support and review"],"correct":1,"exp":"A role brief defines tasks, boundaries, expectations and reporting arrangements.","module":11,"topic":"M11:Volunteer Fundraising"},{"q":"Volunteer Fundraising: What helps volunteers handle gifts or personal information appropriately?","opts":["Role brief","Authorized materials","Support and review","Training and safeguards"],"correct":3,"exp":"Training and safeguards cover authorized processes, privacy and escalation for problems.","module":11,"topic":"M11:Volunteer Fundraising"},{"q":"Volunteer Fundraising: What should volunteers use when describing the cause publicly?","opts":["Role brief","Training and safeguards","Authorized materials","Support and review"],"correct":2,"exp":"Authorized materials support consistent, truthful messages and avoid unsupported promises.","module":11,"topic":"M11:Volunteer Fundraising"},{"q":"Volunteer Fundraising: What should continue while volunteers conduct fundraising activity?","opts":["Support and review","Role brief","Training and safeguards","Authorized materials"],"correct":0,"exp":"Support and review provide help, feedback and accountability for the work.","module":11,"topic":"M11:Volunteer Fundraising"}]},
  {"key":"M11:Peer-to-Peer Fundraising","rows":[{"q":"Peer-to-Peer Fundraising: What distinguishes a peer-to-peer campaign from a central appeal only?","opts":["Supporter-led appeal","Shared campaign guidance","Gift tracking","Responsible oversight"],"correct":0,"exp":"Supporters make appeals through their own networks on behalf of the authorized campaign.","module":11,"topic":"M11:Peer-to-Peer Fundraising"},{"q":"Peer-to-Peer Fundraising: What helps keep those appeals accurate and consistent?","opts":["Shared campaign guidance","Supporter-led appeal","Gift tracking","Responsible oversight"],"correct":0,"exp":"Shared guidance supplies approved messages, boundaries and practical instructions.","module":11,"topic":"M11:Peer-to-Peer Fundraising"},{"q":"Peer-to-Peer Fundraising: What prevents uncertainty about where contributions were received?","opts":["Supporter-led appeal","Gift tracking","Shared campaign guidance","Responsible oversight"],"correct":1,"exp":"Gift tracking records funds and attribution through the approved collection system.","module":11,"topic":"M11:Peer-to-Peer Fundraising"},{"q":"Peer-to-Peer Fundraising: What must the organization still provide despite decentralized appeals?","opts":["Supporter-led appeal","Shared campaign guidance","Gift tracking","Responsible oversight"],"correct":3,"exp":"Responsible oversight checks authorized conduct, information handling and appropriate fund use.","module":11,"topic":"M11:Peer-to-Peer Fundraising"}]},
  {"key":"M11:Community Fundraising","rows":[{"q":"Community Fundraising: What should shape a locally organized appeal or event?","opts":["Feasible event plan","Safe collection process","Transparent account","Community participation"],"correct":3,"exp":"Community participation helps match the activity with local interests and access needs.","module":11,"topic":"M11:Community Fundraising"},{"q":"Community Fundraising: What should be established before announcing the event?","opts":["Community participation","Safe collection process","Transparent account","Feasible event plan"],"correct":3,"exp":"A feasible plan covers purpose, roles, costs, permissions and relevant safety arrangements.","module":11,"topic":"M11:Community Fundraising"},{"q":"Community Fundraising: What should govern how collected funds are handled?","opts":["Safe collection process","Community participation","Feasible event plan","Transparent account"],"correct":0,"exp":"A safe collection process uses authorized controls and records rather than informal untraceable handling.","module":11,"topic":"M11:Community Fundraising"},{"q":"Community Fundraising: What should follow the event?","opts":["Community participation","Feasible event plan","Transparent account","Safe collection process"],"correct":2,"exp":"A transparent account reports receipts, relevant costs and intended use accurately.","module":11,"topic":"M11:Community Fundraising"}]},
  {"key":"M11:Online Fundraising","rows":[{"q":"Online Fundraising: What should help a supporter confirm who is receiving the contribution?","opts":["Clear donation purpose","Verified campaign identity","Usable contribution path","Transaction review"],"correct":1,"exp":"A verified identity and trusted channel reduce confusion and impersonation risk.","module":11,"topic":"M11:Online Fundraising"},{"q":"Online Fundraising: What should the appeal explain before payment?","opts":["Clear donation purpose","Verified campaign identity","Usable contribution path","Transaction review"],"correct":0,"exp":"A clear purpose describes the authorized use and any accepted restrictions honestly.","module":11,"topic":"M11:Online Fundraising"},{"q":"Online Fundraising: What should be tested before launch?","opts":["Verified campaign identity","Clear donation purpose","Transaction review","Usable contribution path"],"correct":3,"exp":"A usable contribution path checks accessibility, instructions and approved payment steps.","module":11,"topic":"M11:Online Fundraising"},{"q":"Online Fundraising: What should reconcile after contributions arrive?","opts":["Verified campaign identity","Clear donation purpose","Usable contribution path","Transaction review"],"correct":3,"exp":"Transaction review compares records, fees, settlements and donor conditions using the approved process.","module":11,"topic":"M11:Online Fundraising"}]},
  {"key":"M11:Mobile Giving","rows":[{"q":"Mobile Giving: What should a fundraiser check on a phone before launching a mobile appeal?","opts":["Informed authorization","Accessible confirmation","Mobile usability","Platform conditions"],"correct":2,"exp":"Mobile usability includes readable information, workable fields and a suitable payment path.","module":11,"topic":"M11:Mobile Giving"},{"q":"Mobile Giving: What should a supporter understand before approving a contribution?","opts":["Informed authorization","Mobile usability","Accessible confirmation","Platform conditions"],"correct":0,"exp":"Informed authorization makes the amount, purpose and any recurring conditions clear.","module":11,"topic":"M11:Mobile Giving"},{"q":"Mobile Giving: What should follow a completed mobile donation?","opts":["Mobile usability","Informed authorization","Accessible confirmation","Platform conditions"],"correct":2,"exp":"An accessible confirmation provides accurate details and appropriate support information.","module":11,"topic":"M11:Mobile Giving"},{"q":"Mobile Giving: What should be verified before choosing or relying on a mobile-giving service?","opts":["Mobile usability","Platform conditions","Informed authorization","Accessible confirmation"],"correct":1,"exp":"Platform conditions include availability, settlement, charges, privacy and applicable rules rather than assumed universal support.","module":11,"topic":"M11:Mobile Giving"}]},
  {"key":"M12:Social Media Fundraising","rows":[{"q":"Social Media Fundraising: What should guide choosing a social channel for an appeal?","opts":["Audience fit","Authorized story","Clear call to action","Response analysis"],"correct":0,"exp":"Audience fit considers where relevant supporters can be reached and how they use the channel.","module":12,"topic":"M12:Social Media Fundraising"},{"q":"Social Media Fundraising: What should precede publishing a person's image and story?","opts":["Audience fit","Clear call to action","Response analysis","Authorized story"],"correct":3,"exp":"An authorized story requires appropriate permission, dignity and privacy safeguards.","module":12,"topic":"M12:Social Media Fundraising"},{"q":"Social Media Fundraising: What should make the intended supporter action understandable?","opts":["Audience fit","Authorized story","Clear call to action","Response analysis"],"correct":2,"exp":"A clear call to action points to a verified suitable contribution route without misleading urgency.","module":12,"topic":"M12:Social Media Fundraising"},{"q":"Social Media Fundraising: What should establish whether attention led to useful campaign outcomes?","opts":["Audience fit","Authorized story","Clear call to action","Response analysis"],"correct":3,"exp":"Response analysis connects engagement with verified actions and costs rather than treating likes as donations.","module":12,"topic":"M12:Social Media Fundraising"}]},
  {"key":"M12:Crowdfunding Campaigns","rows":[{"q":"Crowdfunding Campaigns: What should a crowdfunding page explain about the proposed work?","opts":["Platform terms","Credible project","Progress updates","Completion accountability"],"correct":1,"exp":"A credible project identifies the need, intended use, feasible delivery and important limitations.","module":12,"topic":"M12:Crowdfunding Campaigns"},{"q":"Crowdfunding Campaigns: What should be checked before assuming all pledged money will become usable funds?","opts":["Platform terms","Credible project","Progress updates","Completion accountability"],"correct":0,"exp":"Platform terms can affect eligibility, fees, payout conditions and timing and must be verified.","module":12,"topic":"M12:Crowdfunding Campaigns"},{"q":"Crowdfunding Campaigns: What should supporters receive while the campaign and project develop?","opts":["Progress updates","Credible project","Platform terms","Completion accountability"],"correct":0,"exp":"Progress updates provide accurate status and explain material changes or difficulties.","module":12,"topic":"M12:Crowdfunding Campaigns"},{"q":"Crowdfunding Campaigns: What should follow the campaign's close?","opts":["Credible project","Platform terms","Completion accountability","Progress updates"],"correct":2,"exp":"Completion accountability reconciles funds and reports delivery or unresolved obligations honestly.","module":12,"topic":"M12:Crowdfunding Campaigns"}]},
  {"key":"M12:Email Fundraising","rows":[{"q":"Email Fundraising: What should be established before sending an email appeal list?","opts":["Permitted audience","Relevant message","Clear donation link","Preference management"],"correct":0,"exp":"A permitted audience follows appropriate consent, lawful basis and organizational contact rules.","module":12,"topic":"M12:Email Fundraising"},{"q":"Email Fundraising: What should make the appeal useful to its recipients?","opts":["Relevant message","Permitted audience","Clear donation link","Preference management"],"correct":0,"exp":"A relevant message connects a credible cause with the audience's relationship and interests.","module":12,"topic":"M12:Email Fundraising"},{"q":"Email Fundraising: What should let recipients contribute through the intended verified route?","opts":["Permitted audience","Relevant message","Preference management","Clear donation link"],"correct":3,"exp":"A clear donation link points to an authorized page and should be checked for usability and authenticity.","module":12,"topic":"M12:Email Fundraising"},{"q":"Email Fundraising: What should handle a request to stop receiving appeals?","opts":["Permitted audience","Relevant message","Clear donation link","Preference management"],"correct":3,"exp":"Preference management honors the request through the approved process rather than retaining the person in every campaign.","module":12,"topic":"M12:Email Fundraising"}]},
  {"key":"M12:Website Donation Pages","rows":[{"q":"Website Donation Pages: What should reassure a visitor that the page belongs to the intended organization?","opts":["Purpose and terms","Accessible form","Confirmed transaction","Trusted identity"],"correct":3,"exp":"Trusted identity uses the authorized site and clear organizational information rather than a lookalike appeal.","module":12,"topic":"M12:Website Donation Pages"},{"q":"Website Donation Pages: What should be stated before the donor chooses an amount?","opts":["Trusted identity","Purpose and terms","Accessible form","Confirmed transaction"],"correct":1,"exp":"Purpose and terms explain the intended use and any recurring or restricted conditions accurately.","module":12,"topic":"M12:Website Donation Pages"},{"q":"Website Donation Pages: What should be tested for people using small screens or assistive tools?","opts":["Accessible form","Trusted identity","Purpose and terms","Confirmed transaction"],"correct":0,"exp":"An accessible form provides usable labels, instructions and readable controls.","module":12,"topic":"M12:Website Donation Pages"},{"q":"Website Donation Pages: What should a completed gift process provide?","opts":["Trusted identity","Purpose and terms","Confirmed transaction","Accessible form"],"correct":2,"exp":"A confirmed transaction records the result and supplies accurate acknowledgment or support details under the applicable process.","module":12,"topic":"M12:Website Donation Pages"}]},
  {"key":"M12:SMS Fundraising","rows":[{"q":"SMS Fundraising: What should be checked before sending fundraising texts?","opts":["Concise truthful request","Verified payment route","Opt-out handling","Contact permission"],"correct":3,"exp":"Contact permission and applicable messaging requirements govern whether and how the audience may be approached.","module":12,"topic":"M12:SMS Fundraising"},{"q":"SMS Fundraising: What should a short appeal still communicate accurately?","opts":["Contact permission","Verified payment route","Concise truthful request","Opt-out handling"],"correct":2,"exp":"A concise request states the organization, purpose and intended action without misleading claims.","module":12,"topic":"M12:SMS Fundraising"},{"q":"SMS Fundraising: What should a text link direct donors to?","opts":["Contact permission","Verified payment route","Concise truthful request","Opt-out handling"],"correct":1,"exp":"A verified payment route uses the authorized collection process and should not request sensitive credentials through an untrusted message.","module":12,"topic":"M12:SMS Fundraising"},{"q":"SMS Fundraising: What should follow a recipient's request for no further texts?","opts":["Opt-out handling","Contact permission","Concise truthful request","Verified payment route"],"correct":0,"exp":"Opt-out handling records and honors the preference through the appropriate system.","module":12,"topic":"M12:SMS Fundraising"}]},
  {"key":"M12:Online Payment Platforms","rows":[{"q":"Online Payment Platforms: What should be checked before assuming a platform can accept local donations?","opts":["Fee and settlement terms","Service availability","Appropriate controls","Reconciliation process"],"correct":1,"exp":"Service availability depends on the organization, location, currency and actual provider requirements.","module":12,"topic":"M12:Online Payment Platforms"},{"q":"Online Payment Platforms: What should be understood before forecasting usable receipts?","opts":["Service availability","Fee and settlement terms","Appropriate controls","Reconciliation process"],"correct":1,"exp":"Fee and settlement terms affect the amount and timing available to the organization.","module":12,"topic":"M12:Online Payment Platforms"},{"q":"Online Payment Platforms: What should protect access to payment administration?","opts":["Service availability","Fee and settlement terms","Appropriate controls","Reconciliation process"],"correct":2,"exp":"Appropriate controls limit authorized users and follow the provider's supported protections and response procedures.","module":12,"topic":"M12:Online Payment Platforms"},{"q":"Online Payment Platforms: What should compare payment records with actual funds received?","opts":["Service availability","Fee and settlement terms","Reconciliation process","Appropriate controls"],"correct":2,"exp":"Reconciliation accounts for transactions, charges, refunds and settlement differences using reliable records.","module":12,"topic":"M12:Online Payment Platforms"}]},
  {"key":"M12:Digital Storytelling","rows":[{"q":"Digital Storytelling: What should guide selecting details for a fundraising story?","opts":["Accurate narrative","Participant dignity","Relevant context","Verified outcome"],"correct":0,"exp":"An accurate narrative distinguishes verified events and observations from invented or exaggerated claims.","module":12,"topic":"M12:Digital Storytelling"},{"q":"Digital Storytelling: What should protect a participant whose difficult experience is described?","opts":["Participant dignity","Accurate narrative","Relevant context","Verified outcome"],"correct":0,"exp":"Participant dignity includes appropriate consent, privacy and avoidance of harmful stereotypes.","module":12,"topic":"M12:Digital Storytelling"},{"q":"Digital Storytelling: What should help readers understand the story beyond one isolated example?","opts":["Relevant context","Accurate narrative","Participant dignity","Verified outcome"],"correct":0,"exp":"Relevant context explains the project and limitations rather than presenting one story as the entire population.","module":12,"topic":"M12:Digital Storytelling"},{"q":"Digital Storytelling: What should substantiate the story's claim of project benefit?","opts":["Accurate narrative","Verified outcome","Participant dignity","Relevant context"],"correct":1,"exp":"A verified outcome uses relevant evidence and does not imply causation or guaranteed impact without support.","module":12,"topic":"M12:Digital Storytelling"}]},
  {"key":"M12:Campaign Analytics","rows":[{"q":"Campaign Analytics: What should define a campaign's intended completed action?","opts":["Reliable tracking","Defined conversion","Net contribution","Interpretation limits"],"correct":1,"exp":"A conversion must have a clear meaning, such as a completed donation, distinct from a visit or click.","module":12,"topic":"M12:Campaign Analytics"},{"q":"Campaign Analytics: What should support a report of campaign response?","opts":["Reliable tracking","Defined conversion","Net contribution","Interpretation limits"],"correct":0,"exp":"Reliable tracking uses consistent definitions and checks missing or duplicated records.","module":12,"topic":"M12:Campaign Analytics"},{"q":"Campaign Analytics: What should be examined when comparing fundraising income with campaign costs?","opts":["Defined conversion","Reliable tracking","Net contribution","Interpretation limits"],"correct":2,"exp":"Net contribution considers relevant income less relevant costs and fees using a stated basis.","module":12,"topic":"M12:Campaign Analytics"},{"q":"Campaign Analytics: What should be considered before claiming that a campaign change caused higher donations?","opts":["Defined conversion","Reliable tracking","Net contribution","Interpretation limits"],"correct":3,"exp":"Interpretation limits include audience differences, timing and other factors that may explain the change.","module":12,"topic":"M12:Campaign Analytics"}]},
  {"key":"M13:Building Donor Relationships","rows":[{"q":"Building Donor Relationships: What should guide learning about a donor's priorities?","opts":["Understand interests","Honor commitments","Respect preferences","Maintain accountable contact"],"correct":0,"exp":"Use appropriate listening and legitimate information rather than stereotypes or intrusive research.","module":13,"topic":"M13:Building Donor Relationships"},{"q":"Building Donor Relationships: What supports trust when a donor requests an agreed project update?","opts":["Understand interests","Respect preferences","Honor commitments","Maintain accountable contact"],"correct":2,"exp":"Honor the commitment or promptly explain a necessary change with accurate information.","module":13,"topic":"M13:Building Donor Relationships"},{"q":"Building Donor Relationships: What should guide contact frequency and public acknowledgment?","opts":["Understand interests","Honor commitments","Respect preferences","Maintain accountable contact"],"correct":2,"exp":"Respect preferences and applicable permissions rather than assuming every donor wants the same treatment.","module":13,"topic":"M13:Building Donor Relationships"},{"q":"Building Donor Relationships: What should keep the relationship useful beyond a funding request?","opts":["Understand interests","Honor commitments","Respect preferences","Maintain accountable contact"],"correct":3,"exp":"Accountable contact provides relevant dialogue and verified information about the organization's work.","module":13,"topic":"M13:Building Donor Relationships"}]},
  {"key":"M13:Donor Communication","rows":[{"q":"Donor Communication: What should be defined before contacting a donor?","opts":["Relevant purpose","Truthful content","Suitable channel","Two-way response"],"correct":0,"exp":"A relevant purpose identifies why the communication matters to this relationship.","module":13,"topic":"M13:Donor Communication"},{"q":"Donor Communication: What should support statements about how a gift helped?","opts":["Relevant purpose","Suitable channel","Two-way response","Truthful content"],"correct":3,"exp":"Truthful content uses verified results and makes limitations clear.","module":13,"topic":"M13:Donor Communication"},{"q":"Donor Communication: What should guide choosing a public post, email or private discussion?","opts":["Suitable channel","Relevant purpose","Truthful content","Two-way response"],"correct":0,"exp":"A suitable channel fits sensitivity, preferences, access and the intended interaction.","module":13,"topic":"M13:Donor Communication"},{"q":"Donor Communication: What should an organization provide when a donor raises a reasonable concern?","opts":["Relevant purpose","Two-way response","Truthful content","Suitable channel"],"correct":1,"exp":"A two-way response listens, verifies the issue and supplies appropriate information or action.","module":13,"topic":"M13:Donor Communication"}]},
  {"key":"M13:Thank-You Letters","rows":[{"q":"Thank-You Letters: What should be checked before sending a gift acknowledgment?","opts":["Specific appreciation","Accurate gift details","Appropriate use statement","Correct authorization"],"correct":1,"exp":"Accurate gift details include the relevant donor, amount, date and accepted conditions.","module":13,"topic":"M13:Thank-You Letters"},{"q":"Thank-You Letters: What makes thanks more meaningful than a generic receipt alone?","opts":["Accurate gift details","Appropriate use statement","Specific appreciation","Correct authorization"],"correct":2,"exp":"Specific appreciation connects the contribution with the cause without exaggerating its effect.","module":13,"topic":"M13:Thank-You Letters"},{"q":"Thank-You Letters: What should explain the purpose the organization intends to support?","opts":["Appropriate use statement","Accurate gift details","Specific appreciation","Correct authorization"],"correct":0,"exp":"A use statement must be consistent with donor conditions and authorized plans.","module":13,"topic":"M13:Thank-You Letters"},{"q":"Thank-You Letters: What should govern any formal tax or legal acknowledgment wording?","opts":["Accurate gift details","Specific appreciation","Correct authorization","Appropriate use statement"],"correct":2,"exp":"Use current applicable requirements and an authorized process rather than inventing deductibility claims.","module":13,"topic":"M13:Thank-You Letters"}]},
  {"key":"M13:Donor Recognition","rows":[{"q":"Donor Recognition: What should be checked before publishing a donor's name?","opts":["Suitable acknowledgment","Accurate attribution","Preference record","Permission"],"correct":3,"exp":"Permission and relevant privacy requirements should govern public recognition.","module":13,"topic":"M13:Donor Recognition"},{"q":"Donor Recognition: What should determine whether a donor receives a public mention or a private thanks?","opts":["Permission","Accurate attribution","Preference record","Suitable acknowledgment"],"correct":3,"exp":"Suitable acknowledgment respects preferences, context and the organization's policy.","module":13,"topic":"M13:Donor Recognition"},{"q":"Donor Recognition: What should prevent misleading statements about a donor's contribution?","opts":["Permission","Suitable acknowledgment","Preference record","Accurate attribution"],"correct":3,"exp":"Accurate attribution distinguishes the actual gift, role and project effects.","module":13,"topic":"M13:Donor Recognition"},{"q":"Donor Recognition: What helps future staff honor an anonymous donor's request?","opts":["Permission","Suitable acknowledgment","Accurate attribution","Preference record"],"correct":3,"exp":"A preference record preserves the applicable recognition and contact conditions securely.","module":13,"topic":"M13:Donor Recognition"}]},
  {"key":"M13:Stewardship Reports","rows":[{"q":"Stewardship Reports: What should provide the basis for a stewardship report?","opts":["Use of funds","Agreed purpose","Verified results","Issues and next steps"],"correct":1,"exp":"The agreed purpose and reporting terms define what the donor needs to know.","module":13,"topic":"M13:Stewardship Reports"},{"q":"Stewardship Reports: What should account for the contribution financially?","opts":["Agreed purpose","Use of funds","Verified results","Issues and next steps"],"correct":1,"exp":"Use-of-funds information records relevant receipts, expenditure and balances using a clear basis.","module":13,"topic":"M13:Stewardship Reports"},{"q":"Stewardship Reports: What should support claims about project benefit?","opts":["Agreed purpose","Use of funds","Verified results","Issues and next steps"],"correct":2,"exp":"Verified results use suitable evidence and distinguish activity delivery from outcomes.","module":13,"topic":"M13:Stewardship Reports"},{"q":"Stewardship Reports: What should be included when implementation falls behind?","opts":["Agreed purpose","Use of funds","Verified results","Issues and next steps"],"correct":3,"exp":"Explain material issues and authorized next steps honestly rather than hiding the delay.","module":13,"topic":"M13:Stewardship Reports"}]},
  {"key":"M13:Donor Retention","rows":[{"q":"Donor Retention: What should be examined before assuming why donors stop giving?","opts":["Relevant stewardship","Preference respect","Relationship experience","Retention measure"],"correct":2,"exp":"Relationship experience includes communication, trust, circumstances and donor feedback rather than one untested explanation.","module":13,"topic":"M13:Donor Retention"},{"q":"Donor Retention: What can support continued engagement after a gift?","opts":["Relevant stewardship","Relationship experience","Preference respect","Retention measure"],"correct":0,"exp":"Relevant stewardship provides thanks, credible updates and suitable opportunities for dialogue.","module":13,"topic":"M13:Donor Retention"},{"q":"Donor Retention: What should be honored when a donor wants fewer appeals?","opts":["Relationship experience","Preference respect","Relevant stewardship","Retention measure"],"correct":1,"exp":"Preference respect maintains appropriate boundaries and avoids pressure.","module":13,"topic":"M13:Donor Retention"},{"q":"Donor Retention: What should be defined before reporting the percentage of donors who gave again?","opts":["Relationship experience","Relevant stewardship","Preference respect","Retention measure"],"correct":3,"exp":"A retention measure needs a clear prior donor group, later period and consistent handling of records.","module":13,"topic":"M13:Donor Retention"}]},
  {"key":"M13:Managing Donor Databases","rows":[{"q":"Managing Donor Databases: What should be corrected when a donor has duplicate or wrong contact records?","opts":["Accurate records","Appropriate access","Preference fields","Data quality review"],"correct":0,"exp":"Accurate records support reliable communication and gift accounting.","module":13,"topic":"M13:Managing Donor Databases"},{"q":"Managing Donor Databases: What should limit who can view sensitive donor information?","opts":["Appropriate access","Accurate records","Preference fields","Data quality review"],"correct":0,"exp":"Appropriate access follows organizational roles, permissions and applicable requirements.","module":13,"topic":"M13:Managing Donor Databases"},{"q":"Managing Donor Databases: What should capture restrictions on appeals or public recognition?","opts":["Accurate records","Preference fields","Appropriate access","Data quality review"],"correct":1,"exp":"Preference fields help authorized staff honor the donor's recorded choices.","module":13,"topic":"M13:Managing Donor Databases"},{"q":"Managing Donor Databases: What should periodically check missing values, duplicates and outdated information?","opts":["Accurate records","Appropriate access","Data quality review","Preference fields"],"correct":2,"exp":"Data quality review improves reliability while following suitable retention and correction processes.","module":13,"topic":"M13:Managing Donor Databases"}]},
  {"key":"M13:CRM Systems","rows":[{"q":"CRM Systems: What should a CRM help coordinate beyond storing names?","opts":["Shared authorized record","Task follow-up","Relationship workflow","Governed reporting"],"correct":2,"exp":"A relationship workflow connects relevant interactions, responsibilities and next actions.","module":13,"topic":"M13:CRM Systems"},{"q":"CRM Systems: What reduces inconsistent information across fundraising staff?","opts":["Relationship workflow","Shared authorized record","Task follow-up","Governed reporting"],"correct":1,"exp":"A shared authorized record uses reliable data while respecting access boundaries.","module":13,"topic":"M13:CRM Systems"},{"q":"CRM Systems: What helps a promised donor update reach the responsible staff member?","opts":["Relationship workflow","Shared authorized record","Governed reporting","Task follow-up"],"correct":3,"exp":"Task follow-up records ownership, due dates and completion within the system.","module":13,"topic":"M13:CRM Systems"},{"q":"CRM Systems: What should make CRM analysis trustworthy and responsible?","opts":["Relationship workflow","Shared authorized record","Task follow-up","Governed reporting"],"correct":3,"exp":"Governed reporting uses clear definitions, appropriate permissions and checks on data quality.","module":13,"topic":"M13:CRM Systems"}]},
  {"key":"M14:Award Acceptance","rows":[{"q":"Award Acceptance: What should precede agreeing to a grant award?","opts":["Delivery readiness","Terms review","Authorized approval","Acceptance record"],"correct":1,"exp":"Terms review examines the scope, permitted use, obligations and incorporated requirements.","module":14,"topic":"M14:Award Acceptance"},{"q":"Award Acceptance: What should be checked before promising compliance with the award?","opts":["Terms review","Authorized approval","Acceptance record","Delivery readiness"],"correct":3,"exp":"Delivery readiness includes capacity, cash timing, systems and realistic responsibilities.","module":14,"topic":"M14:Award Acceptance"},{"q":"Award Acceptance: What should establish who may formally accept the award?","opts":["Terms review","Delivery readiness","Acceptance record","Authorized approval"],"correct":3,"exp":"Authorized approval follows the entity's governance and the funder's process.","module":14,"topic":"M14:Award Acceptance"},{"q":"Award Acceptance: What should be retained after acceptance?","opts":["Acceptance record","Terms review","Delivery readiness","Authorized approval"],"correct":0,"exp":"An acceptance record preserves approved terms, relevant correspondence and responsibilities.","module":14,"topic":"M14:Award Acceptance"}]},
  {"key":"M14:Grant Agreements","rows":[{"q":"Grant Agreements: What part of an agreement defines the work and intended deliverables?","opts":["Funding conditions","Reporting obligations","Scope and results","Change authority"],"correct":2,"exp":"Scope and results establish the authorized project rather than leaving it to later assumption.","module":14,"topic":"M14:Grant Agreements"},{"q":"Grant Agreements: What part determines the grant amount and permitted financial use?","opts":["Scope and results","Funding conditions","Reporting obligations","Change authority"],"correct":1,"exp":"Funding conditions must be read with incorporated rules and relevant payment arrangements.","module":14,"topic":"M14:Grant Agreements"},{"q":"Grant Agreements: What part establishes the required reports and timing?","opts":["Scope and results","Reporting obligations","Funding conditions","Change authority"],"correct":1,"exp":"Reporting obligations specify what must be submitted, when and through which route.","module":14,"topic":"M14:Grant Agreements"},{"q":"Grant Agreements: What should be checked before altering a funded activity or budget?","opts":["Scope and results","Change authority","Funding conditions","Reporting obligations"],"correct":1,"exp":"Change authority identifies when and how funder or organizational approval is required.","module":14,"topic":"M14:Grant Agreements"}]},
  {"key":"M14:Financial Management","rows":[{"q":"Financial Management: What helps distinguish restricted grant activity within organizational accounts?","opts":["Authorized expenditure","Supporting evidence","Separate tracking","Reconciliation"],"correct":2,"exp":"Separate tracking uses suitable records and classifications without automatically assuming a separate bank account is universally required.","module":14,"topic":"M14:Financial Management"},{"q":"Financial Management: What should govern spending under the award?","opts":["Separate tracking","Supporting evidence","Authorized expenditure","Reconciliation"],"correct":2,"exp":"Authorized expenditure follows approved purposes, budget and applicable conditions.","module":14,"topic":"M14:Financial Management"},{"q":"Financial Management: What should support a cost recorded against the grant?","opts":["Supporting evidence","Separate tracking","Authorized expenditure","Reconciliation"],"correct":0,"exp":"Evidence may include the relevant receipt, invoice, allocation or other documentation required by the award.","module":14,"topic":"M14:Financial Management"},{"q":"Financial Management: What should compare records with transactions and balances?","opts":["Reconciliation","Separate tracking","Authorized expenditure","Supporting evidence"],"correct":0,"exp":"Reconciliation identifies differences and resolves them through the appropriate process.","module":14,"topic":"M14:Financial Management"}]},
  {"key":"M14:Procurement","rows":[{"q":"Procurement: What should determine the process for buying goods under a grant?","opts":["Applicable rules","Relevant specification","Fair comparison","Documented decision"],"correct":0,"exp":"Applicable rules include the actual award, organizational policy and current local requirements.","module":14,"topic":"M14:Procurement"},{"q":"Procurement: What helps compare offers for the same needed goods or services?","opts":["Relevant specification","Applicable rules","Fair comparison","Documented decision"],"correct":0,"exp":"A relevant specification states suitable requirements without unjustified supplier favoritism.","module":14,"topic":"M14:Procurement"},{"q":"Procurement: What should support choosing between credible suppliers?","opts":["Applicable rules","Fair comparison","Relevant specification","Documented decision"],"correct":1,"exp":"Fair comparison uses appropriate criteria such as quality, total cost, delivery and risk.","module":14,"topic":"M14:Procurement"},{"q":"Procurement: What should preserve the reason and authority for the purchase?","opts":["Documented decision","Applicable rules","Relevant specification","Fair comparison"],"correct":0,"exp":"A documented decision records evidence, conflicts, approval and the selected option.","module":14,"topic":"M14:Procurement"}]},
  {"key":"M14:Compliance","rows":[{"q":"Compliance: What helps the organization know every significant award requirement?","opts":["Obligation register","Control owner","Evidence record","Issue response"],"correct":0,"exp":"An obligation register organizes relevant terms, dates and responsibilities.","module":14,"topic":"M14:Compliance"},{"q":"Compliance: What makes a required check part of actual work?","opts":["Obligation register","Control owner","Evidence record","Issue response"],"correct":1,"exp":"A control owner is assigned the task, authority and resources to operate the control.","module":14,"topic":"M14:Compliance"},{"q":"Compliance: What supports a later review that the control was performed?","opts":["Obligation register","Control owner","Issue response","Evidence record"],"correct":3,"exp":"An evidence record documents relevant actions accurately and securely.","module":14,"topic":"M14:Compliance"},{"q":"Compliance: What should follow discovering a material compliance problem?","opts":["Obligation register","Issue response","Control owner","Evidence record"],"correct":1,"exp":"An issue response uses the approved route for assessment, correction and any required notification.","module":14,"topic":"M14:Compliance"}]},
  {"key":"M14:Monitoring Activities","rows":[{"q":"Monitoring Activities: What should project monitoring compare actual activity with?","opts":["Field evidence","Barrier identification","Authorized adjustment","Work-plan comparison"],"correct":3,"exp":"The approved work plan provides relevant expected tasks, dates and delivery standards.","module":14,"topic":"M14:Monitoring Activities"},{"q":"Monitoring Activities: What should substantiate a statement that an activity occurred?","opts":["Work-plan comparison","Barrier identification","Authorized adjustment","Field evidence"],"correct":3,"exp":"Field evidence must be suitable and reliable while protecting participant information.","module":14,"topic":"M14:Monitoring Activities"},{"q":"Monitoring Activities: What should be investigated when activities are delayed?","opts":["Work-plan comparison","Field evidence","Authorized adjustment","Barrier identification"],"correct":3,"exp":"Barrier identification examines capacity, dependencies and other relevant causes rather than assuming poor effort.","module":14,"topic":"M14:Monitoring Activities"},{"q":"Monitoring Activities: What should govern a proposed change resulting from monitoring?","opts":["Work-plan comparison","Field evidence","Authorized adjustment","Barrier identification"],"correct":2,"exp":"Authorized adjustment follows the agreement's change process and considers effects on budget and results.","module":14,"topic":"M14:Monitoring Activities"}]},
  {"key":"M14:Risk Management","rows":[{"q":"Risk Management: What makes an identified project risk accountable?","opts":["Response plan","Owned risk","Trigger monitoring","Residual exposure"],"correct":1,"exp":"An owned risk has a named role responsible for appropriate monitoring and action.","module":14,"topic":"M14:Risk Management"},{"q":"Risk Management: What prepares the project to handle an identified uncertain event?","opts":["Owned risk","Response plan","Trigger monitoring","Residual exposure"],"correct":1,"exp":"A response plan defines feasible mitigation or contingency and required authority.","module":14,"topic":"M14:Risk Management"},{"q":"Risk Management: What signals that a risk response may need to be activated?","opts":["Owned risk","Response plan","Trigger monitoring","Residual exposure"],"correct":2,"exp":"Trigger monitoring checks specified evidence or thresholds related to the exposure.","module":14,"topic":"M14:Risk Management"},{"q":"Risk Management: What should be reviewed after risk controls are applied?","opts":["Owned risk","Response plan","Trigger monitoring","Residual exposure"],"correct":3,"exp":"Residual exposure is the remaining risk and should not be assumed eliminated merely because a control exists.","module":14,"topic":"M14:Risk Management"}]},
  {"key":"M14:Reporting Requirements","rows":[{"q":"Reporting Requirements: What should determine the sections of a grant report?","opts":["Reporting calendar","Approval process","Submission record","Required content"],"correct":3,"exp":"Required content follows the actual award instructions and relevant templates.","module":14,"topic":"M14:Reporting Requirements"},{"q":"Reporting Requirements: What helps avoid missing interim or final reporting dates?","opts":["Required content","Approval process","Submission record","Reporting calendar"],"correct":3,"exp":"A reporting calendar lists due dates, preparation time and responsible roles.","module":14,"topic":"M14:Reporting Requirements"},{"q":"Reporting Requirements: What should ensure financial and program statements are reviewed before sending?","opts":["Approval process","Required content","Reporting calendar","Submission record"],"correct":0,"exp":"An approval process assigns appropriate checking and authorized sign-off.","module":14,"topic":"M14:Reporting Requirements"},{"q":"Reporting Requirements: What should confirm the report was delivered through the required route?","opts":["Required content","Reporting calendar","Approval process","Submission record"],"correct":3,"exp":"A submission record retains appropriate acknowledgment and the approved copy without assuming receipt proves acceptance.","module":14,"topic":"M14:Reporting Requirements"}]},
  {"key":"M15:Monitoring & Evaluation Basics","rows":[{"q":"Monitoring & Evaluation Basics: What describes ongoing tracking of implementation and relevant results?","opts":["Evaluation","Learning","Accountability","Monitoring"],"correct":3,"exp":"Monitoring checks progress over time using defined information needs and measures.","module":15,"topic":"M15:Monitoring & Evaluation Basics"},{"q":"Monitoring & Evaluation Basics: What examines the value or performance of an intervention through suitable questions and methods?","opts":["Monitoring","Learning","Accountability","Evaluation"],"correct":3,"exp":"Evaluation makes reasoned judgments supported by evidence, rather than simply listing activities.","module":15,"topic":"M15:Monitoring & Evaluation Basics"},{"q":"Monitoring & Evaluation Basics: What uses findings to improve future choices?","opts":["Monitoring","Learning","Evaluation","Accountability"],"correct":1,"exp":"Learning connects evidence and reflection with a specific change in practice.","module":15,"topic":"M15:Monitoring & Evaluation Basics"},{"q":"Monitoring & Evaluation Basics: What demonstrates responsibility to participants and funders?","opts":["Monitoring","Accountability","Evaluation","Learning"],"correct":1,"exp":"Accountability uses honest reporting, appropriate explanation and corrective action when necessary.","module":15,"topic":"M15:Monitoring & Evaluation Basics"}]},
  {"key":"M15:Performance Indicators","rows":[{"q":"Performance Indicators: What should prevent two teams from counting the same result differently?","opts":["Baseline","Target","Source and method","Definition"],"correct":3,"exp":"An indicator definition states unit, scope and relevant counting rules.","module":15,"topic":"M15:Performance Indicators"},{"q":"Performance Indicators: What identifies the starting position against which change is examined?","opts":["Baseline","Definition","Target","Source and method"],"correct":0,"exp":"A baseline uses a suitable period and method comparable with later measurement.","module":15,"topic":"M15:Performance Indicators"},{"q":"Performance Indicators: What states the intended level by an agreed time?","opts":["Target","Definition","Baseline","Source and method"],"correct":0,"exp":"A target should be justified and feasible rather than invented to impress a donor.","module":15,"topic":"M15:Performance Indicators"},{"q":"Performance Indicators: What enables collection of the indicator's information?","opts":["Definition","Baseline","Source and method","Target"],"correct":2,"exp":"The source and method must be suitable, reliable and practical for the required measure.","module":15,"topic":"M15:Performance Indicators"}]},
  {"key":"M15:Data Collection","rows":[{"q":"Data Collection: What should guide the selection of information during implementation?","opts":["Consistent procedure","Indicator alignment","Participant protection","Quality assurance"],"correct":1,"exp":"Indicator alignment connects each data item with an actual monitoring or evaluation need.","module":15,"topic":"M15:Data Collection"},{"q":"Data Collection: What helps data collected by different staff remain comparable?","opts":["Indicator alignment","Participant protection","Quality assurance","Consistent procedure"],"correct":3,"exp":"A consistent procedure defines questions, units, timing and recording practice.","module":15,"topic":"M15:Data Collection"},{"q":"Data Collection: What should govern handling of identifiable beneficiary information?","opts":["Participant protection","Indicator alignment","Consistent procedure","Quality assurance"],"correct":0,"exp":"Participant protection uses appropriate consent, safeguarding, privacy and access controls.","module":15,"topic":"M15:Data Collection"},{"q":"Data Collection: What should detect missing or implausible entries before reporting?","opts":["Indicator alignment","Consistent procedure","Quality assurance","Participant protection"],"correct":2,"exp":"Quality assurance checks completeness, consistency and reliability and documents corrections appropriately.","module":15,"topic":"M15:Data Collection"}]},
  {"key":"M15:Progress Reports","rows":[{"q":"Progress Reports: What should an interim report say about planned activities?","opts":["Implementation status","Results evidence","Variance explanation","Next-period actions"],"correct":0,"exp":"Implementation status states completed, ongoing and delayed work accurately.","module":15,"topic":"M15:Progress Reports"},{"q":"Progress Reports: What should support claims about the project's developing outcomes?","opts":["Implementation status","Results evidence","Variance explanation","Next-period actions"],"correct":1,"exp":"Results evidence distinguishes verified change from activity counts and estimates.","module":15,"topic":"M15:Progress Reports"},{"q":"Progress Reports: What should explain a difference between planned and actual delivery?","opts":["Implementation status","Results evidence","Next-period actions","Variance explanation"],"correct":3,"exp":"Variance explanation identifies relevant causes and limitations without hiding unfavorable findings.","module":15,"topic":"M15:Progress Reports"},{"q":"Progress Reports: What should connect the report with continuing implementation?","opts":["Implementation status","Next-period actions","Results evidence","Variance explanation"],"correct":1,"exp":"Next-period actions state feasible work, owners and any required approvals or support.","module":15,"topic":"M15:Progress Reports"}]},
  {"key":"M15:Financial Reports","rows":[{"q":"Financial Reports: What should make expenditure figures comparable across reports?","opts":["Consistent classification","Budget-to-actual comparison","Supporting reconciliation","Required presentation basis"],"correct":0,"exp":"Consistent classification uses the relevant approved categories and definitions.","module":15,"topic":"M15:Financial Reports"},{"q":"Financial Reports: What shows whether expenditure differs from the approved plan?","opts":["Consistent classification","Budget-to-actual comparison","Supporting reconciliation","Required presentation basis"],"correct":1,"exp":"Budget-to-actual comparison identifies variances that should be interpreted in context.","module":15,"topic":"M15:Financial Reports"},{"q":"Financial Reports: What should support the reported balance and transaction totals?","opts":["Consistent classification","Budget-to-actual comparison","Required presentation basis","Supporting reconciliation"],"correct":3,"exp":"Reconciliation checks records and resolves relevant differences using suitable evidence.","module":15,"topic":"M15:Financial Reports"},{"q":"Financial Reports: What should determine whether the funder wants receipts, expenditure or another specified basis?","opts":["Required presentation basis","Consistent classification","Budget-to-actual comparison","Supporting reconciliation"],"correct":0,"exp":"Use the required presentation basis from the actual instructions rather than assuming every donor report uses the same rules.","module":15,"topic":"M15:Financial Reports"}]},
  {"key":"M15:Impact Measurement","rows":[{"q":"Impact Measurement: What does impact assessment examine beyond immediate activity outputs?","opts":["Causal uncertainty","Suitable evidence","Unintended consequences","Higher-level effects"],"correct":3,"exp":"Higher-level effects include significant broader changes relevant to the intervention and context.","module":15,"topic":"M15:Impact Measurement"},{"q":"Impact Measurement: What should be considered before saying the project alone caused a later improvement?","opts":["Higher-level effects","Suitable evidence","Causal uncertainty","Unintended consequences"],"correct":2,"exp":"Causal uncertainty requires examining alternative explanations and the limits of the evaluation design.","module":15,"topic":"M15:Impact Measurement"},{"q":"Impact Measurement: What should support a claim about substantial change?","opts":["Higher-level effects","Causal uncertainty","Suitable evidence","Unintended consequences"],"correct":2,"exp":"Suitable evidence matches the question and context rather than relying only on a favorable anecdote.","module":15,"topic":"M15:Impact Measurement"},{"q":"Impact Measurement: What should an assessment consider besides intended benefits?","opts":["Unintended consequences","Higher-level effects","Causal uncertainty","Suitable evidence"],"correct":0,"exp":"Unintended consequences may include adverse or uneven effects that honest evaluation must examine.","module":15,"topic":"M15:Impact Measurement"}]},
  {"key":"M15:Final Reports","rows":[{"q":"Final Reports: What should a final report distinguish from future proposals?","opts":["Outcome assessment","Financial account","Remaining obligations","Delivered work"],"correct":3,"exp":"Delivered work describes what actually occurred and identifies incomplete commitments.","module":15,"topic":"M15:Final Reports"},{"q":"Final Reports: What should compare intended change with the evidence obtained?","opts":["Delivered work","Outcome assessment","Financial account","Remaining obligations"],"correct":1,"exp":"Outcome assessment states findings, methods and relevant limitations.","module":15,"topic":"M15:Final Reports"},{"q":"Final Reports: What should explain use of funds at the end of the award?","opts":["Delivered work","Outcome assessment","Financial account","Remaining obligations"],"correct":2,"exp":"A financial account follows the funder's required basis and reconciles relevant amounts and balances.","module":15,"topic":"M15:Final Reports"},{"q":"Final Reports: What should be identified before assuming the award is fully closed?","opts":["Remaining obligations","Delivered work","Outcome assessment","Financial account"],"correct":0,"exp":"Remaining obligations may include approvals, records, asset conditions or other agreement-specific closeout requirements.","module":15,"topic":"M15:Final Reports"}]},
  {"key":"M15:Lessons Learned","rows":[{"q":"Lessons Learned: What makes a lesson more useful than a vague statement that communication matters?","opts":["Specific observation","Cause reflection","Transfer limitation","Improvement action"],"correct":0,"exp":"A specific observation identifies the situation, behavior and result that informed the learning.","module":15,"topic":"M15:Lessons Learned"},{"q":"Lessons Learned: What should be examined before recommending a change?","opts":["Specific observation","Transfer limitation","Cause reflection","Improvement action"],"correct":2,"exp":"Cause reflection considers why the result occurred and whether other factors contributed.","module":15,"topic":"M15:Lessons Learned"},{"q":"Lessons Learned: What should be recognized before applying a lesson in a different setting?","opts":["Transfer limitation","Specific observation","Cause reflection","Improvement action"],"correct":0,"exp":"Transfer limitations explain how context or evidence may affect whether the change fits elsewhere.","module":15,"topic":"M15:Lessons Learned"},{"q":"Lessons Learned: What turns a lesson into continuing practice?","opts":["Specific observation","Cause reflection","Transfer limitation","Improvement action"],"correct":3,"exp":"An improvement action assigns a feasible change, owner and way to review its effect.","module":15,"topic":"M15:Lessons Learned"}]},
  {"key":"M16:AI for Proposal Drafting","rows":[{"q":"AI for Proposal Drafting: What should precede asking an AI tool to draft a proposal section?","opts":["Verified input brief","Bounded drafting task","Human fact-check","Authorized information handling"],"correct":0,"exp":"A verified input brief gives the actual facts, requirements and assumptions rather than asking the tool to invent organizational evidence.","module":16,"topic":"M16:AI for Proposal Drafting"},{"q":"AI for Proposal Drafting: What makes the AI request easier to assess?","opts":["Bounded drafting task","Verified input brief","Human fact-check","Authorized information handling"],"correct":0,"exp":"A bounded task specifies the section, purpose and constraints without delegating the entire funding judgment blindly.","module":16,"topic":"M16:AI for Proposal Drafting"},{"q":"AI for Proposal Drafting: What should follow receiving a fluent AI-generated draft?","opts":["Verified input brief","Human fact-check","Bounded drafting task","Authorized information handling"],"correct":1,"exp":"Human fact-checking verifies claims, calculations, references and fit with the actual instructions.","module":16,"topic":"M16:AI for Proposal Drafting"},{"q":"AI for Proposal Drafting: What should govern whether confidential organizational data is entered into an AI service?","opts":["Verified input brief","Bounded drafting task","Authorized information handling","Human fact-check"],"correct":2,"exp":"Use only appropriately authorized tools and information handling under the organization's requirements.","module":16,"topic":"M16:AI for Proposal Drafting"}]},
  {"key":"M16:ChatGPT for Grant Writing","rows":[{"q":"ChatGPT for Grant Writing: What should a drafting prompt provide instead of asking for invented success statistics?","opts":["Explicit constraints","Draft verification","Responsible ownership","Evidence-grounded prompt"],"correct":3,"exp":"An evidence-grounded prompt supplies verified information and identifies gaps that must remain unresolved.","module":16,"topic":"M16:ChatGPT for Grant Writing"},{"q":"ChatGPT for Grant Writing: What should tell the tool about word limits and required questions?","opts":["Explicit constraints","Evidence-grounded prompt","Draft verification","Responsible ownership"],"correct":0,"exp":"Explicit constraints help shape the draft but do not prove that the output complies.","module":16,"topic":"M16:ChatGPT for Grant Writing"},{"q":"ChatGPT for Grant Writing: What should a writer do before using generated references or figures?","opts":["Evidence-grounded prompt","Explicit constraints","Draft verification","Responsible ownership"],"correct":2,"exp":"Verify them against reliable sources and the actual organizational records; plausible wording is not evidence.","module":16,"topic":"M16:ChatGPT for Grant Writing"},{"q":"ChatGPT for Grant Writing: Who remains responsible for a submitted application assisted by an AI tool?","opts":["Responsible ownership","Evidence-grounded prompt","Explicit constraints","Draft verification"],"correct":0,"exp":"The authorized people and organization remain responsible for its accuracy, approvals and obligations.","module":16,"topic":"M16:ChatGPT for Grant Writing"}]},
  {"key":"M16:Grant Management Software","rows":[{"q":"Grant Management Software: What should guide selecting a grant-management system?","opts":["Workflow configuration","Data integrity","Requirements fit","Access governance"],"correct":2,"exp":"Requirements fit connects the tool with actual award tracking, reporting and organizational needs.","module":16,"topic":"M16:Grant Management Software"},{"q":"Grant Management Software: What should turn award deadlines into usable tasks?","opts":["Requirements fit","Data integrity","Access governance","Workflow configuration"],"correct":3,"exp":"Workflow configuration defines stages, owners, reminders and relevant approvals.","module":16,"topic":"M16:Grant Management Software"},{"q":"Grant Management Software: What should support trustworthy reports from the system?","opts":["Data integrity","Requirements fit","Workflow configuration","Access governance"],"correct":0,"exp":"Data integrity depends on accurate records, consistent definitions and appropriate checks.","module":16,"topic":"M16:Grant Management Software"},{"q":"Grant Management Software: What should protect sensitive grant and participant information?","opts":["Requirements fit","Workflow configuration","Data integrity","Access governance"],"correct":3,"exp":"Access governance assigns suitable permissions and accountability rather than giving every user all records.","module":16,"topic":"M16:Grant Management Software"}]},
  {"key":"M16:CRM Software","rows":[{"q":"CRM Software: What should define the purpose of a fundraising CRM?","opts":["Record migration","User workflow","Permission checks","Relationship requirements"],"correct":3,"exp":"Relationship requirements identify the information and actions needed for responsible engagement.","module":16,"topic":"M16:CRM Software"},{"q":"CRM Software: What should be checked when moving donor records into a new system?","opts":["Relationship requirements","User workflow","Record migration","Permission checks"],"correct":2,"exp":"Record migration reconciles fields, duplicates, preferences and authorized data use.","module":16,"topic":"M16:CRM Software"},{"q":"CRM Software: What helps staff use the CRM consistently in daily work?","opts":["Relationship requirements","Record migration","User workflow","Permission checks"],"correct":2,"exp":"A user workflow defines how interactions, tasks and updates should be recorded.","module":16,"topic":"M16:CRM Software"},{"q":"CRM Software: What should be reviewed before sharing a CRM report widely?","opts":["Relationship requirements","Record migration","User workflow","Permission checks"],"correct":3,"exp":"Permission checks ensure the audience and content fit authorized access and privacy responsibilities.","module":16,"topic":"M16:CRM Software"}]},
  {"key":"M16:Microsoft Excel for Budgets","rows":[{"q":"Microsoft Excel for Budgets: What should distinguish estimated quantities and rates from calculated totals?","opts":["Transparent formulas","Validation checks","Version control","Clear inputs"],"correct":3,"exp":"Clear inputs use labeled units and stated assumptions so a reviewer can understand the basis.","module":16,"topic":"M16:Microsoft Excel for Budgets"},{"q":"Microsoft Excel for Budgets: What makes a line-total calculation easier to inspect?","opts":["Clear inputs","Validation checks","Transparent formulas","Version control"],"correct":2,"exp":"Transparent formulas connect quantity and unit cost without hidden hard-coded replacements.","module":16,"topic":"M16:Microsoft Excel for Budgets"},{"q":"Microsoft Excel for Budgets: What should detect inconsistent totals or missing values?","opts":["Clear inputs","Transparent formulas","Validation checks","Version control"],"correct":2,"exp":"Validation checks verify arithmetic, required fields and reconciliation with the funding request.","module":16,"topic":"M16:Microsoft Excel for Budgets"},{"q":"Microsoft Excel for Budgets: What should prevent submission of an old spreadsheet after revisions?","opts":["Version control","Clear inputs","Transparent formulas","Validation checks"],"correct":0,"exp":"Version control identifies the approved current file and records relevant changes.","module":16,"topic":"M16:Microsoft Excel for Budgets"}]},
  {"key":"M16:Canva for Proposal Graphics","rows":[{"q":"Canva for Proposal Graphics: What should determine whether to add a graphic to a proposal?","opts":["Accurate data","Relevant visual","Accessible design","Funder format check"],"correct":1,"exp":"A relevant visual clarifies information needed by the reviewer rather than serving decoration alone.","module":16,"topic":"M16:Canva for Proposal Graphics"},{"q":"Canva for Proposal Graphics: What should support numbers shown in a chart?","opts":["Relevant visual","Accessible design","Accurate data","Funder format check"],"correct":2,"exp":"Accurate data and labels must match the verified narrative and source definitions.","module":16,"topic":"M16:Canva for Proposal Graphics"},{"q":"Canva for Proposal Graphics: What helps readers interpret the visual without relying only on color?","opts":["Relevant visual","Accurate data","Accessible design","Funder format check"],"correct":2,"exp":"Accessible design uses readable contrast, labels and explanations.","module":16,"topic":"M16:Canva for Proposal Graphics"},{"q":"Canva for Proposal Graphics: What should be verified before inserting a designed graphic into an application?","opts":["Relevant visual","Funder format check","Accurate data","Accessible design"],"correct":1,"exp":"The funder's format rules govern whether and how visuals may be used, including file and page constraints.","module":16,"topic":"M16:Canva for Proposal Graphics"}]},
  {"key":"M16:Productivity Tools","rows":[{"q":"Productivity Tools: What prevents proposal actions from being scattered across informal messages?","opts":["Task capture","Priority sequence","Shared responsibility","Tool review"],"correct":0,"exp":"Task capture creates a reliable record of work and commitments.","module":16,"topic":"M16:Productivity Tools"},{"q":"Productivity Tools: What should organize tasks before an external deadline?","opts":["Task capture","Priority sequence","Shared responsibility","Tool review"],"correct":1,"exp":"A priority sequence considers dependencies, preparation time and required approvals.","module":16,"topic":"M16:Productivity Tools"},{"q":"Productivity Tools: What should clarify who obtains a particular attachment?","opts":["Task capture","Priority sequence","Tool review","Shared responsibility"],"correct":3,"exp":"Shared responsibility records appropriate owners and supporting roles rather than assuming everyone will do it.","module":16,"topic":"M16:Productivity Tools"},{"q":"Productivity Tools: What should examine whether a tool actually helps the team?","opts":["Task capture","Priority sequence","Shared responsibility","Tool review"],"correct":3,"exp":"Tool review checks reliability, usability and useful delivery rather than adding administration for its own sake.","module":16,"topic":"M16:Productivity Tools"}]},
  {"key":"M16:Document Collaboration","rows":[{"q":"Document Collaboration: What should establish who may view, edit or approve a proposal?","opts":["Revision tracking","Resolved review","Role permissions","Approved final copy"],"correct":2,"exp":"Role permissions protect information and make responsibility explicit.","module":16,"topic":"M16:Document Collaboration"},{"q":"Document Collaboration: What helps reviewers see what changed between drafts?","opts":["Role permissions","Resolved review","Approved final copy","Revision tracking"],"correct":3,"exp":"Revision tracking records edits and supports comparison without treating every draft as approved.","module":16,"topic":"M16:Document Collaboration"},{"q":"Document Collaboration: What should happen after reviewers comment on inconsistent figures?","opts":["Role permissions","Revision tracking","Resolved review","Approved final copy"],"correct":2,"exp":"Resolved review reconciles the issue and records the decision rather than merely hiding comments.","module":16,"topic":"M16:Document Collaboration"},{"q":"Document Collaboration: What should be submitted after collaboration ends?","opts":["Approved final copy","Role permissions","Revision tracking","Resolved review"],"correct":0,"exp":"An approved final copy is checked, authorized and distinguished from earlier versions.","module":16,"topic":"M16:Document Collaboration"}]},
  {"key":"M17:Becoming a Freelance Grant Writer","rows":[{"q":"Becoming a Freelance Grant Writer: What should a freelancer define before accepting an assignment?","opts":["Demonstrated capability","Service scope","Professional boundaries","Sustainable work plan"],"correct":1,"exp":"Service scope states the work to be performed, deliverables and responsibilities.","module":17,"topic":"M17:Becoming a Freelance Grant Writer"},{"q":"Becoming a Freelance Grant Writer: What should support claims that the freelancer can do the work?","opts":["Service scope","Professional boundaries","Demonstrated capability","Sustainable work plan"],"correct":2,"exp":"Demonstrated capability uses accurate examples and relevant experience without guaranteeing awards.","module":17,"topic":"M17:Becoming a Freelance Grant Writer"},{"q":"Becoming a Freelance Grant Writer: What should be established when a client requests legal or tax advice beyond the writer's competence?","opts":["Service scope","Demonstrated capability","Sustainable work plan","Professional boundaries"],"correct":3,"exp":"Professional boundaries identify limits and refer appropriate matters to qualified specialists.","module":17,"topic":"M17:Becoming a Freelance Grant Writer"},{"q":"Becoming a Freelance Grant Writer: What should consider capacity, costs and realistic commitments across clients?","opts":["Service scope","Sustainable work plan","Demonstrated capability","Professional boundaries"],"correct":1,"exp":"A sustainable work plan avoids accepting incompatible deadlines or unsupported delivery promises.","module":17,"topic":"M17:Becoming a Freelance Grant Writer"}]},
  {"key":"M17:Building a Portfolio","rows":[{"q":"Building a Portfolio: What should precede including a client's proposal in a public portfolio?","opts":["Authorized sample","Personal contribution","Evidence of quality","Learning record"],"correct":0,"exp":"An authorized sample respects permission and confidentiality and may require suitable anonymization.","module":17,"topic":"M17:Building a Portfolio"},{"q":"Building a Portfolio: What should distinguish a freelancer's role from other contributors' work?","opts":["Authorized sample","Personal contribution","Evidence of quality","Learning record"],"correct":1,"exp":"Personal contribution states accurately which research, drafting or coordination the writer performed.","module":17,"topic":"M17:Building a Portfolio"},{"q":"Building a Portfolio: What should support a claim of strong proposal work?","opts":["Authorized sample","Personal contribution","Learning record","Evidence of quality"],"correct":3,"exp":"Evidence of quality can include relevant review, requirement fit and verified consistency rather than funding success alone.","module":17,"topic":"M17:Building a Portfolio"},{"q":"Building a Portfolio: What shows how the writer improved after feedback?","opts":["Authorized sample","Personal contribution","Evidence of quality","Learning record"],"correct":3,"exp":"A learning record explains the feedback, revision and next development action.","module":17,"topic":"M17:Building a Portfolio"}]},
  {"key":"M17:Finding Clients","rows":[{"q":"Finding Clients: What should guide selecting potential clients?","opts":["Credible introduction","Fit conversation","Relevant prospect","Agreed next step"],"correct":2,"exp":"A relevant prospect has needs and expectations compatible with the writer's capability and ethical boundaries.","module":17,"topic":"M17:Finding Clients"},{"q":"Finding Clients: What should an initial service message communicate?","opts":["Relevant prospect","Credible introduction","Fit conversation","Agreed next step"],"correct":1,"exp":"A credible introduction states truthful experience and the value of a defined service without an award guarantee.","module":17,"topic":"M17:Finding Clients"},{"q":"Finding Clients: What should be explored before accepting the assignment?","opts":["Fit conversation","Relevant prospect","Credible introduction","Agreed next step"],"correct":0,"exp":"A fit conversation clarifies evidence availability, scope, deadlines, capacity and approvals.","module":17,"topic":"M17:Finding Clients"},{"q":"Finding Clients: What makes a promising conversation actionable?","opts":["Agreed next step","Relevant prospect","Credible introduction","Fit conversation"],"correct":0,"exp":"An agreed next step names the responsible person, needed information and timing without assuming a contract already exists.","module":17,"topic":"M17:Finding Clients"}]},
  {"key":"M17:Proposal Pricing","rows":[{"q":"Proposal Pricing: What should be established before quoting for grant-writing work?","opts":["Effort estimate","Nonpercentage fee basis","Clear payment terms","Defined deliverables"],"correct":3,"exp":"Defined deliverables specify research, drafting, revisions and any exclusions.","module":17,"topic":"M17:Proposal Pricing"},{"q":"Proposal Pricing: What should support the proposed price?","opts":["Defined deliverables","Nonpercentage fee basis","Clear payment terms","Effort estimate"],"correct":3,"exp":"An effort estimate considers complexity, evidence availability, review cycles and realistic time.","module":17,"topic":"M17:Proposal Pricing"},{"q":"Proposal Pricing: Under AFP ethical standards, what should replace a commission calculated from donations secured?","opts":["Defined deliverables","Nonpercentage fee basis","Effort estimate","Clear payment terms"],"correct":1,"exp":"A nonpercentage fee basis prices professional work rather than taking a percentage of philanthropic contributions; check other applicable obligations.","module":17,"topic":"M17:Proposal Pricing"},{"q":"Proposal Pricing: What should a client understand before accepting the quote?","opts":["Defined deliverables","Effort estimate","Clear payment terms","Nonpercentage fee basis"],"correct":2,"exp":"Payment terms specify amounts, milestones, timing and any suitable conditions without promising a funding result.","module":17,"topic":"M17:Proposal Pricing"}]},
  {"key":"M17:Writing Contracts","rows":[{"q":"Writing Contracts: What should define what the writer and client each supply?","opts":["Scope and responsibilities","Review and acceptance","Confidentiality terms","Change and payment process"],"correct":0,"exp":"Scope and responsibilities distinguish deliverables, inputs, approvals and exclusions.","module":17,"topic":"M17:Writing Contracts"},{"q":"Writing Contracts: What should establish how drafts are reviewed and accepted?","opts":["Scope and responsibilities","Review and acceptance","Confidentiality terms","Change and payment process"],"correct":1,"exp":"Review and acceptance terms define cycles, criteria and authorized sign-off.","module":17,"topic":"M17:Writing Contracts"},{"q":"Writing Contracts: What should govern use of client or beneficiary information?","opts":["Scope and responsibilities","Confidentiality terms","Review and acceptance","Change and payment process"],"correct":1,"exp":"Confidentiality terms must fit authorization, organizational requirements and applicable law.","module":17,"topic":"M17:Writing Contracts"},{"q":"Writing Contracts: What should govern extra work or delayed payment?","opts":["Scope and responsibilities","Change and payment process","Review and acceptance","Confidentiality terms"],"correct":1,"exp":"A change and payment process makes conditions explicit; unclear legal implications require qualified advice.","module":17,"topic":"M17:Writing Contracts"}]},
  {"key":"M17:Personal Branding","rows":[{"q":"Personal Branding: What should form the basis of a grant writer's professional reputation?","opts":["Relevant positioning","Consistent conduct","Verified examples","Truthful capability"],"correct":3,"exp":"Truthful capability is grounded in actual skill and experience rather than fabricated qualifications.","module":17,"topic":"M17:Personal Branding"},{"q":"Personal Branding: What helps a writer explain which clients or assignments they can serve?","opts":["Truthful capability","Relevant positioning","Consistent conduct","Verified examples"],"correct":1,"exp":"Relevant positioning connects suitable services with real needs without making universal claims.","module":17,"topic":"M17:Personal Branding"},{"q":"Personal Branding: What sustains credibility after an initial introduction?","opts":["Consistent conduct","Truthful capability","Relevant positioning","Verified examples"],"correct":0,"exp":"Consistent conduct aligns promises, communication and ethical practice.","module":17,"topic":"M17:Personal Branding"},{"q":"Personal Branding: What supports a public claim of professional quality?","opts":["Verified examples","Truthful capability","Relevant positioning","Consistent conduct"],"correct":0,"exp":"Verified examples accurately show work and role while respecting permission and confidentiality.","module":17,"topic":"M17:Personal Branding"}]},
  {"key":"M17:LinkedIn Optimization","rows":[{"q":"LinkedIn Optimization: What should a profile emphasize for a grant-writing role?","opts":["Accurate achievement","Authorized work example","Role-relevant profile","Professional contact"],"correct":2,"exp":"A role-relevant profile highlights suitable capabilities and experience clearly.","module":17,"topic":"M17:LinkedIn Optimization"},{"q":"LinkedIn Optimization: What should replace an unsupported claim that the writer guarantees funding?","opts":["Role-relevant profile","Authorized work example","Accurate achievement","Professional contact"],"correct":2,"exp":"An accurate achievement states the actual work and verified result without overstating influence or certainty.","module":17,"topic":"M17:LinkedIn Optimization"},{"q":"LinkedIn Optimization: What should be checked before posting a proposal extract?","opts":["Role-relevant profile","Accurate achievement","Professional contact","Authorized work example"],"correct":3,"exp":"An authorized work example requires suitable permission and removal of protected information.","module":17,"topic":"M17:LinkedIn Optimization"},{"q":"LinkedIn Optimization: What should guide responding to an inquiry through a professional platform?","opts":["Role-relevant profile","Professional contact","Accurate achievement","Authorized work example"],"correct":1,"exp":"Professional contact uses a clear, respectful response and moves sensitive details through an appropriate authorized route.","module":17,"topic":"M17:LinkedIn Optimization"}]},
  {"key":"M17:Interview Preparation","rows":[{"q":"Interview Preparation: What should support an answer about previous grant-writing work?","opts":["Process explanation","Honest limitation","Clarifying question","Evidence-based example"],"correct":3,"exp":"An evidence-based example describes context, personal contribution and an accurate result.","module":17,"topic":"M17:Interview Preparation"},{"q":"Interview Preparation: What should a candidate explain when asked how they approach a new opportunity?","opts":["Process explanation","Evidence-based example","Honest limitation","Clarifying question"],"correct":0,"exp":"A process explanation covers screening, evidence, coordination, drafting, review and submission requirements.","module":17,"topic":"M17:Interview Preparation"},{"q":"Interview Preparation: What should a candidate do if asked about experience they do not have?","opts":["Honest limitation","Evidence-based example","Process explanation","Clarifying question"],"correct":0,"exp":"An honest limitation avoids fabrication and may identify relevant transferable experience.","module":17,"topic":"M17:Interview Preparation"},{"q":"Interview Preparation: What helps the candidate assess whether the role is feasible?","opts":["Clarifying question","Evidence-based example","Process explanation","Honest limitation"],"correct":0,"exp":"A clarifying question explores expectations, resources, responsibilities and review arrangements.","module":17,"topic":"M17:Interview Preparation"}]}];
 var exams=[{"q":"A workshop budget includes 40 participants at $5 each for two sessions and two facilitator days at $150 per day. What is the combined cost?","opts":["$700","$350","$500","$1,100"],"correct":0,"exp":"Participant costs are 40 × 5 × 2 = $400; facilitator costs are 2 × 150 = $300; the combined budget is $700.","module":8,"topic":"M8:Examination scenario"},{"q":"A supporter gave only for school materials, but the organization wants to use the balance for an unrelated campaign. What should the stewardship officer do first?","opts":["Spend it because the overall mission is charitable","Rename the campaign as school materials","Check the restriction and seek any required donor authorization before changing use","Hide the remaining balance in the thank-you note"],"correct":2,"exp":"Stewardship respects donor intent, records the restricted balance and obtains the required permission before changing its use.","module":13,"topic":"M13:Examination scenario"},{"q":"An award email arrives with a revised budget and reporting conditions. What should happen before authorized acceptance?","opts":["Assume the original application overrides the award","Review the actual terms, obligations and capacity with the authorized decision makers","Announce unrestricted money is available","Let any volunteer sign without review"],"correct":1,"exp":"Award acceptance requires review of the actual agreement, resources, obligations and signing authority.","module":14,"topic":"M14:Examination scenario"},{"q":"A program records 60 training completions and reports that household income improved solely because of the training. What is the evidence problem?","opts":["Completions automatically prove a causal impact","Income never needs a baseline","Any large participant count proves sustainability","Completions show an output; income change and causal attribution require further evidence"],"correct":3,"exp":"An output count is not evidence of income change or sole causation. Outcomes and attribution need an appropriate design and evidence.","module":15,"topic":"M15:Examination scenario"},{"q":"An indicator counts unique women completing a course, but staff add every attendance visit. What should be corrected?","opts":["Change the target to match the inflated total","Call all visits unique people","Remove the indicator definition","Apply the unique-person completion definition and remove duplicate visit counts"],"correct":3,"exp":"A consistent indicator definition controls the unit, eligibility and completion rule; counting visits as unique completers inflates results.","module":15,"topic":"M15:Examination scenario"},{"q":"A survey reports 90% satisfaction from nine respondents out of 100 invited. What should the report include?","opts":["Only the 90% headline","The respondent count, response rate and limits on generalizing the result","A claim that all 100 learners were satisfied","A fabricated response for everyone who did not reply"],"correct":1,"exp":"Report the sample and response rate, 9%, and consider nonresponse bias before making wider claims.","module":15,"topic":"M15:Examination scenario"},{"q":"A quarterly report shows an activity delayed by rain. Which response supports useful monitoring?","opts":["Delete the activity from earlier plans","Report it as completed to keep the chart green","Describe the delay, revised timing, effects and responsible recovery action","Wait until the final report to disclose it"],"correct":2,"exp":"Progress reports compare actual delivery with the plan and explain deviations and corrective actions honestly.","module":15,"topic":"M15:Examination scenario"},{"q":"A financial report shows an approved supplies budget of $1,200 and actual spending of $1,050. What is the underspend?","opts":["$2,250","$1,050","$150, with the reason and implications still to be explained","$350"],"correct":2,"exp":"The difference is $1,200 − $1,050 = $150. An underspend is not automatically a success; explain delivery, timing and any authorized action.","module":15,"topic":"M15:Examination scenario"},{"q":"Interview participants name a teacher and disclose private family circumstances. What should be done before sharing findings publicly?","opts":["Publish the entire transcript for transparency","Replace the names but retain every identifying detail","Use authorized, appropriately anonymized findings and protect identifying details","Share the raw file with any interested donor"],"correct":2,"exp":"Evidence reporting must protect sensitive information and consider indirect identification, consent and authorized access.","module":15,"topic":"M15:Examination scenario"},{"q":"A final evaluation finds some benefits but also increased travel costs for participants. What should the conclusions do?","opts":["Remove the adverse effect because it was not in the original objective","Report intended results and unintended effects with evidence and limitations","Declare that every effect is positive","Treat evaluation as a publicity brochure"],"correct":1,"exp":"A useful evaluation examines context, intended and unintended effects, and limitations instead of selectively reporting favorable findings.","module":15,"topic":"M15:Examination scenario"},{"q":"A team notes that late procurement repeatedly delayed sessions. What turns the observation into a usable lesson?","opts":["Assign an earlier procurement milestone, owner and future check","Store the complaint without action","Blame one person without investigating the process","Repeat the same schedule automatically"],"correct":0,"exp":"Lessons learned connect evidence about causes to a feasible change, responsible owner and review of whether it works.","module":15,"topic":"M15:Examination scenario"},{"q":"An NGO proposal claims ten years of service, but records support only four. What should the writer submit?","opts":["Ten years because it sounds stronger","An invented founding date","No organizational history at all","The verified four-year history with documented achievements"],"correct":3,"exp":"An NGO proposal must accurately describe organizational experience and support claims with records.","module":18,"topic":"M18:Examination scenario"},{"q":"An education proposal promises improved literacy but budgets only an opening ceremony. What is the strongest revision?","opts":["Add more publicity photos","Keep the budget because ceremonies guarantee literacy","Remove every outcome measure","Connect teaching activities, assessment measures and costs to the literacy objective"],"correct":3,"exp":"Proposal coherence requires activities and resources that plausibly deliver and measure the stated learning outcome.","module":18,"topic":"M18:Examination scenario"},{"q":"A health project plans community information sessions. What should its proposal establish?","opts":["A promise that sessions cure every illness","Unverified medical claims copied from advertising","Participant diagnoses written by the grant writer","Appropriate qualified oversight, referral arrangements and evidence-based scope"],"correct":3,"exp":"Health proposals require suitable expertise and a realistic scope; a grant writer should not invent clinical claims or act beyond their competence.","module":18,"topic":"M18:Examination scenario"},{"q":"A youth project wants to publish identifiable stories from minors. Which planning decision is best?","opts":["Assume enrollment permits unlimited publicity","Use appropriate safeguarding, consent processes and privacy protection before publication","Publish names to make fundraising persuasive","Let volunteers share any story without review"],"correct":1,"exp":"Youth proposals should address safeguarding and applicable consent and privacy requirements, including publicity risks.","module":18,"topic":"M18:Examination scenario"},{"q":"A women's empowerment project was designed without consulting the women it intends to serve. What should the team do?","opts":["Assume one leader represents every woman","Keep the design because funders prefer speed","Invent quotes to show participation","Seek inclusive, safe consultation and revise the design using participants' priorities"],"correct":3,"exp":"Consultation should recognize diverse needs and barriers and allow affected people to influence the design safely.","module":18,"topic":"M18:Examination scenario"},{"q":"An agriculture proposal budgets equipment but has no plan for seasonal use, maintenance or training. What is missing?","opts":["An operational plan matching seasons, skills, maintenance and ongoing costs","Only a larger photograph of the equipment","A guarantee of identical yields in every season","A promise to ignore equipment failure"],"correct":0,"exp":"Agriculture projects need feasible operations and assumptions; equipment alone does not establish useful or sustained results.","module":18,"topic":"M18:Examination scenario"},{"q":"A small business applies to a fund restricted to registered nonprofit organizations. What should the proposal team do?","opts":["Describe the business as a nonprofit without evidence","Confirm actual eligibility and decline or redirect the application if the business is ineligible","Submit under someone else's registration","Assume every small business qualifies for any grant"],"correct":1,"exp":"Eligibility is governed by the actual opportunity; changing labels or using another entity's documents does not establish eligibility.","module":18,"topic":"M18:Examination scenario"},{"q":"A community development project selects a meeting site inaccessible to some intended participants. What should be revised?","opts":["The attendance target to exclude those participants","The report so the barrier is invisible","The donor name only","The access arrangements, budget and consultation plan"],"correct":3,"exp":"An inclusive community proposal should identify access barriers and plan feasible changes with affected people.","module":18,"topic":"M18:Examination scenario"},{"q":"A fundraising campaign targets $8,000 gross and expects $1,200 in campaign costs. What amount is available before any other obligations?","opts":["$8,000 net","$9,200 net","$1,200 net","$6,800 net"],"correct":3,"exp":"Net proceeds are gross receipts minus costs, $8,000 − $1,200 = $6,800; restrictions and further obligations still need consideration.","module":18,"topic":"M18:Examination scenario"},{"q":"A donor presentation includes an impressive number with no source. What should happen before the presentation?","opts":["Increase it for emphasis","Call it audited without an audit","Verify, qualify or remove the number and provide a traceable source","Hide the source slide"],"correct":2,"exp":"A credible presentation uses checkable evidence and distinguishes verified facts from estimates and assumptions.","module":18,"topic":"M18:Examination scenario"},{"q":"An NGO project partner has not agreed to its assigned responsibilities. What should the proposal team secure?","opts":["A signature copied from an old letter","A documented, authorized agreement on realistic roles and commitments","An assumption that silence means agreement","A claim that the partner will supply unlimited funds"],"correct":1,"exp":"Partnership claims should reflect actual consent, resources and responsibilities rather than unsupported commitments.","module":18,"topic":"M18:Examination scenario"},{"q":"An education budget funds 100 textbooks for 40 learners without explaining shared use or replacements. What should a reviewer request?","opts":["An automatic rejection of all textbook costs","A quantity rationale linked to the delivery plan and unit cost","Removal of unit costs","A higher quantity with no justification"],"correct":1,"exp":"A budget justification explains why quantities and costs are appropriate for the planned activities and beneficiaries.","module":18,"topic":"M18:Examination scenario"},{"q":"A project reports that a campaign reached 10,000 social accounts. What additional measure would test fundraising performance?","opts":["Only the number of likes","A claim that every view is a donation","Total followers described as money received","Completed donations and net receipts using reliable attribution rules"],"correct":3,"exp":"Reach is a communication measure; fundraising performance requires donation and financial evidence, with attribution limits explained.","module":18,"topic":"M18:Examination scenario"},{"q":"A grant proposal's work plan says six months, but its budget funds three months of staff. What should the writer do?","opts":["Leave both versions for the donor to choose","Delete staff costs","Reconcile the timeline, staffing assumptions and budget before submission","Extend the narrative without recalculating costs"],"correct":2,"exp":"Consistent planning requires the narrative, schedule and budget to describe the same delivery assumptions.","module":18,"topic":"M18:Examination scenario"},{"q":"A donor asks whether a proposal has already been funded elsewhere. What is the correct response?","opts":["Hide other awards to maximize receipts","Disclose relevant committed funding and explain how duplication will be avoided","Charge both donors for the same expense without authorization","Say all funds are unrestricted regardless of terms"],"correct":1,"exp":"Funding sources and covered costs should be transparent and reconciled to avoid unauthorized duplicate financing.","module":18,"topic":"M18:Examination scenario"},{"q":"A capstone opportunity deadline is tomorrow, but a mandatory organizational registration takes longer. What is the sound decision?","opts":["Upload a fabricated registration document","Check the actual rule and use a feasible opportunity rather than falsely claiming registration","Assume the deadline waives eligibility","Ask the writer to sign as the registering authority"],"correct":1,"exp":"Capstone opportunity selection must consider verified eligibility and readiness, including realistic preparation time.","module":19,"topic":"M19:Examination scenario"},{"q":"A capstone needs assessment relies on one donor's opinion about a community. What strengthens it?","opts":["Repeating that opinion in every section","Inventing survey responses","Relevant local evidence and inclusive stakeholder consultation with limitations recorded","Removing the needs section"],"correct":2,"exp":"A needs assessment should triangulate appropriate evidence and affected people's perspectives rather than rely on a single unsupported claim.","module":19,"topic":"M19:Examination scenario"},{"q":"A capstone work plan gives every task to 'the team' without dates. What should be added?","opts":["Only decorative icons","A guarantee of no delays","A single end date with no task ownership","Specific responsibilities, sequence and milestones"],"correct":3,"exp":"A usable work plan identifies who does what and when, including dependencies and review milestones.","module":19,"topic":"M19:Examination scenario"},{"q":"A proposed capstone budget assumes an indirect cost rate without checking the funder. What should the learner do?","opts":["Apply the same rate to every donor","Describe the assumption as a mandatory law","Verify permitted treatment, rate and cost base before calculating indirect costs","Charge indirect costs twice"],"correct":2,"exp":"Indirect cost eligibility, rates and bases depend on applicable rules and the actual award; there is no universal default rate.","module":19,"topic":"M19:Examination scenario"},{"q":"A complete capstone proposal has a target outcome with no indicator or data source. What is needed?","opts":["A larger target number alone","An assertion that measurement is unnecessary","A photo used as proof of every outcome","A measurable definition, source, timing and responsible owner"],"correct":3,"exp":"An outcome monitoring plan requires an operational indicator and feasible evidence collection, not just an ambitious target.","module":19,"topic":"M19:Examination scenario"},{"q":"A capstone fundraising strategy expects a future bequest to pay next month's invoices. What is the issue?","opts":["A bequest is always immediately settled","Every pledge is a bank receipt","Uncertain future planned giving cannot be treated as available cash","The invoices must therefore be canceled"],"correct":2,"exp":"A strategy must distinguish commitments and uncertain future gifts from cash that is actually available when expenses fall due.","module":19,"topic":"M19:Examination scenario"},{"q":"A learner presents a capstone proposal and is asked about a risk not considered. What is a professional response?","opts":["Invent a completed analysis on the spot","Acknowledge the gap, discuss evidence and revise the risk response","Claim the project has no risks","Blame the audience for asking"],"correct":1,"exp":"Professional presentation includes honest limits and constructive revision rather than fabricated certainty.","module":19,"topic":"M19:Examination scenario"},{"q":"A final capstone review finds the attachment list does not match the funder's checklist. What should the team do?","opts":["Submit unrelated documents to increase volume","Assume the reviewer will find missing files elsewhere","Remove the checklist","Reconcile each requirement and confirm current, correct attachments"],"correct":3,"exp":"Final review should trace every required attachment and instruction before authorized submission.","module":19,"topic":"M19:Examination scenario"},{"q":"A capstone budget includes a donation already assigned to another restricted project. What should happen?","opts":["Count it again because both projects are charitable","Treat restricted funds as unrestricted cash","Exclude unavailable funding or obtain the required authorized change and document it","Hide the assignment from the funding table"],"correct":2,"exp":"Cost-sharing and available funding must reflect actual commitments, restrictions and permissions.","module":19,"topic":"M19:Examination scenario"},{"q":"A learner uses a real former client's proposal in a public portfolio. What is necessary first?","opts":["Appropriate authorization and removal or protection of confidential information","Only changing the cover color","Assuming the client waived confidentiality by hiring the writer","Publishing the client's donor contacts"],"correct":0,"exp":"Portfolio evidence should show skills without exposing confidential or unauthorized client material.","module":19,"topic":"M19:Examination scenario"},{"q":"Two reviewers edit different copies of the capstone budget. What avoids submitting inconsistent figures?","opts":["Attach both conflicting versions","Let the larger total win automatically","Use a controlled current version, resolve changes and record approval","Remove calculations from the final budget"],"correct":2,"exp":"Document control and reconciliation help ensure one approved proposal and consistent financial figures.","module":19,"topic":"M19:Examination scenario"},{"q":"An AI tool generates a plausible community statistic for the capstone. How should it be handled?","opts":["Accept it because the wording sounds authoritative","Describe the tool as the community survey","Use it if the proposal deadline is close","Verify it against an appropriate source or remove it; do not present invented data"],"correct":3,"exp":"AI-generated claims are not verified evidence; human review must check facts, sources and permissions.","module":19,"topic":"M19:Examination scenario"},{"q":"A learner's capstone monitoring plan collects names although only aggregate attendance is needed. What is the best revision?","opts":["Collect every personal detail for possible future use","Publish the attendance sheet","Remove all monitoring because privacy matters","Collect the minimum appropriate data and specify protection and retention arrangements"],"correct":3,"exp":"Proportionate data collection can support monitoring while limiting unnecessary personal information and access.","module":19,"topic":"M19:Examination scenario"},{"q":"A capstone donor pitch promises an award is guaranteed if the proposal is polished. What should the learner say?","opts":["Professional writing guarantees funding","A strong proposal improves clarity and fit but award decisions remain with the funder","Payment to a writer secures the award","Every eligible applicant must receive money"],"correct":1,"exp":"Grant awards depend on funder criteria, resources and competition; professional work must not promise guaranteed success.","module":19,"topic":"M19:Examination scenario"},{"q":"A capstone reflection says 'we learned a lot' with no evidence. What improves it?","opts":["Identify personal contributions, feedback, changes and next learning actions","Copy the project introduction","Claim all team work was done by one learner","List only the final score"],"correct":0,"exp":"A useful reflection links personal learning to specific work, evidence, feedback and future improvements.","module":19,"topic":"M19:Examination scenario"}];
 var topics={},practice={};
 DATA.forEach(function(t){topics[t.key]=t.rows;practice[t.key]=t.rows.slice(0,3);});
 window.TIH_GRANT_QUESTIONS={revision:1,topics:topics,exams:exams};
 window.TIH_TOPIC_QUIZZES=window.TIH_TOPIC_QUIZZES||{};window.TIH_TOPIC_QUIZZES['grant-writing']=practice;
})();
